NAN_HOOK = """window.__nan = []; const sa = Element.prototype.setAttribute;
Element.prototype.setAttribute = function (k, v) { if (String(v) === "NaN") window.__nan.push(this.tagName + "." + k); return sa.call(this, k, v); };"""

# #1029: the size sweeps check a fixed sample of their widths on every run, and every width with BROWSER_CHECK_FULL=1
# (CI's nightly run, and on demand and on a release). Each sample keeps the edges, each side of the layout's breakpoints
# (480, 520, 600, 640, 700, 760, 900 and 1200 px) and the widths its issue found broken.
FULL = os.environ.get("BROWSER_CHECK_FULL") == "1"


def sweep(every, sample):
    """#1029: a size sweep's widths, in their order: all of `every` with BROWSER_CHECK_FULL=1, else those in `sample`;
    and what its check's name adds when they're the sample."""
    every, keep = list(every), set(sample)
    assert keep <= set(every), sorted(keep - set(every))
    kept = every if FULL else [x for x in every if x in keep]
    return kept, "" if FULL else f" (on this run {len(kept)} of those {len(every)} widths, a fixed sample; BROWSER_CHECK_FULL=1 for all, #1029)"


# #1029: the checks in parts, run at once on CI (check.yml's browser jobs), each with its own app: `--part NAME` runs
# what every part shares (the app, the pages under the CSP, the sign-in), then only the try blocks main() begins with
# a start_part(…) naming it, each to the next start_part(…); no --part runs them all, in order, as one. A check is in
# the part (or parts) of the start_part(…) above it.
PARTS = ("records", "views", "pages")
PART = None   # this run's --part


class Skip(Exception):
    """A part this run leaves out (start_part()), caught where its try block ends."""


def start_part(*names):
    """#1029: a part's try block's first line: the block is skipped unless this run is one of those parts', or all of
    them. A block of two parts makes what a later part's checks need of an earlier one's: run in each."""
    assert set(names) <= set(PARTS), names
    if PART is not None and PART not in names:
        raise Skip(names)


HTML_RECORD = 990001


def add_html_record(build):
    """An .htm record with a stylesheet and a picture saved beside it, like portal exports have (the demo's only
    document is a PDF), so the drawer is checked with a record that loads its own parts."""
    folder = os.path.join(build, "files", "visit summary_files")
    os.makedirs(folder, exist_ok=True)
    with open(os.path.join(build, "files", "visit summary.htm"), "w", encoding="utf-8") as f:
        f.write('<link rel="stylesheet" href="visit summary_files/style.css"><p id="t">Visit summary</p>'
                '<img id="i" src="visit summary_files/logo.png">'
                '<meta http-equiv="refresh" content="1; url=https://example.invalid/moved">')   # it mustn't move its tab (#221)
    with open(os.path.join(folder, "style.css"), "w", encoding="utf-8") as f:
        f.write("#t { color: rgb(255, 0, 0) }")
    with open(os.path.join(folder, "logo.png"), "wb") as f:   # a 1x1 PNG
        f.write(bytes.fromhex("89504e470d0a1a0a0000000d49484452000000010000000108060000001f15c4890000000d49444154789c63"
                              "f8ffff3f0005fe02fea7d6a4ba0000000049454e44ae426082"))
    path = os.path.join(build, "data.json")
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    data["events"].append({"id": HTML_RECORD, "t": "2025-10-01T10:00:00", "k": "document", "title": "Visit summary (HTM)", "sub": "Test"})
    data["details"][str(HTML_RECORD)] = {"type": "file", "ext": "htm", "url": "files/visit summary.htm"}
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f)


