def clear_of_bar(page):
    """Scroll up just enough that no control lies half under the sticky top bar, before axe looks at a part scrolled
    into view: axe counts a control the bar half covers as too small a target (2.5.8), so where the scroll happened to
    stop would decide the check. Returns how far it scrolled."""
    return page.evaluate(CLEAR_OF_BAR_JS)


# #356: a browser without CSS anchor positioning (Firefox and Safari before their releases with it; Chromium can't turn
# it off): CSS.supports() answers false for it, and app.css comes with every anchor-positioning declaration and
# @position-try rule dropped, as a parser that doesn't know them would, and its @supports not (anchor-name: --a) blocks
# unwrapped, so menus and the tooltip are placed by nav.js's menuPlace and util.js's tooltip as such a browser would
NO_ANCHOR_INIT = """(() => { const o = CSS.supports.bind(CSS); CSS.supports = function (a, b) { const s = String(a) + ' ' + String(b ?? '');
  if (/anchor|position-area|position-try/.test(s)) return false; return b === undefined ? o(a) : o(a, b); }; })();"""


def no_anchor_css(css):
    out, i, key = [], 0, "@supports not (anchor-name: --a){"
    while (j := css.find(key, i)) >= 0:
        out.append(css[i:j])
        k = m = j + len(key)
        depth = 1
        while depth:
            depth += {"{": 1, "}": -1}.get(css[m], 0)
            m += 1
        out.append(css[k:m - 1])
        i = m
    css = "".join(out) + css[i:]
    css = re.sub(r"@position-try\s+--[\w-]+\s*\{[^}]*\}", "", css)
    css = re.sub(r"(?<=[{;])\s*(anchor-name|anchor-scope|position-anchor|position-try-fallbacks|position-try-order|position-try|position-area|position-visibility)\s*:[^;{}]*;?", "", css)
    return re.sub(r"(?<=[{;])\s*[a-z-]+\s*:[^;{}]*(anchor\(|anchor-center|anchor-size\()[^;{}]*;?", "", css)


def without_anchor_positioning(ctx):
    """The context's pages as in a browser without CSS anchor positioning (#356)."""
    ctx.add_init_script(NO_ANCHOR_INIT)
    def css(route):
        r = route.fetch()
        route.fulfill(response=r, body=no_anchor_css(r.text()))
    ctx.route(re.compile(r".*/css/app\.css(\?.*)?$"), css)


# #358: what Chromium's accessibility tree, what a screen reader is given, says of the first element a selector
# finds: [its name, its description] (None when there's no such element)
def ax_said(page, selector):
    cdp = page.context.new_cdp_session(page)
    try:
        root = cdp.send("DOM.getDocument", {"depth": 0})["root"]["nodeId"]
        node = cdp.send("DOM.querySelector", {"nodeId": root, "selector": selector})["nodeId"]
        if not node:
            return None
        n = cdp.send("Accessibility.getPartialAXTree", {"nodeId": node, "fetchRelatives": False})["nodes"][0]
        return [n.get("name", {}).get("value", ""), n.get("description", {}).get("value", "")]
    finally:
        cdp.detach()


# …and every element of the page whose description its name already says, as [role, name, description]
def ax_echoes(page):
    cdp = page.context.new_cdp_session(page)
    try:
        nodes = cdp.send("Accessibility.getFullAXTree")["nodes"]
    finally:
        cdp.detach()
    norm = lambda s: " ".join(str(s).split()).lower()
    out = []
    for n in nodes:
        name, desc = norm(n.get("name", {}).get("value", "")), norm(n.get("description", {}).get("value", ""))
        if desc and not n.get("ignored") and desc in name:
            out.append([n.get("role", {}).get("value"), name, desc])
    return out


# #257: the app's icons are Lucide's, from www/icons/sprite.svg, in place of Unicode glyphs. On the page as it is: a glyph
# still standing for an icon in a button's or link's text (or drawn by its ::before or ::after), an arrow or + at either
# end of one, or one that is only "?"; an icon not drawn (its <use> found no symbol: 0 by 0, waited for once, as the sprite
# may still be loading); an svg.icon neither hidden from screen readers nor named; a button or link with only an icon in it
# and no name. ▲ and ▼ stay text, the out-of-range marks (docs/accessibility.md), and so does an arrow inside a sentence.
# #355: and in any text shown (each text node, and each element's ::before and ::after), no symbol from the blocks icons
# came from (arrows, technical, geometric shapes, symbols, dingbats, braille, ⋯, pictographs), but the marks that mean
# something and are said in words beside them: ▲ ▼ (out of range), ◆ ● ■ ○ ◇ (legends and flags; • is punctuation),
# ← → in a sentence and ⌘ in "⌘C". A help text naming "the ◐ button" fails here. ↑ and ↓ before a number are a tile's
# change ("↓ 5.3 lb this period", #298, #623), text and not an icon; alone, as a sort's arrow, they are still one.
ICON_GLYPHS = "✓✔✕✖×⇔◐✎⋯⚠↗⠿▾✗↑↓⌘"
TEXT_MARKS = "▲▼◆●■○◇←→⌘"
ICON_AUDIT = r"""([glyphs, marks]) => {
  const vis = n => n.checkVisibility(), out = {n: 0, glyph: [], text: [], hidden: [], unnamed: [], blank: []};
  const sym = /[\u2190-\u21FF\u22EF\u2300-\u23FF\u25A0-\u27BF\u2800-\u28FF\u2B00-\u2BFF\u{1F300}-\u{1FAFF}]/gu;
  const chg = t => t.replace(/[↑↓](?= \d)/g, '');   // a change's arrow (#298)
  const odd = t => [...new Set(chg(t).match(sym) || [])].filter(c => !marks.includes(c)).join('');
  const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  for (let t; (t = w.nextNode());) {
    const p = t.parentElement, o = odd(t.textContent);
    if (o && p && !p.closest('script, style, template, noscript') && vis(p)) out.text.push(`${o} in “${t.textContent.trim().slice(0, 50)}”`);
  }
  for (const e of document.body.querySelectorAll('*')) for (const ps of ['::before', '::after']) {
    const o = odd(getComputedStyle(e, ps).content);
    if (o && vis(e)) out.text.push(`${o} in ${e.tagName.toLowerCase()}.${[...e.classList].join('.')}${ps}`);
  }
  const name = n => (n.getAttribute('aria-label') || n.getAttribute('title') || '').trim() ||
    (n.getAttribute('aria-labelledby') || '').split(/\s+/).map(id => document.getElementById(id)?.textContent.trim()).join('');
  for (const b of document.querySelectorAll('button, a[href], [role=button], [role^=menuitem], summary')) {
    if (!vis(b)) continue;
    const t = chg(b.textContent.trim()), cs = p => getComputedStyle(b, p).content;
    if ([...glyphs].some(g => t.includes(g) || cs('::before').includes(g) || cs('::after').includes(g)) || /^[→+?]|→$|^\?$/.test(t))
      out.glyph.push(t.slice(0, 40) || b.id || b.className);
    if (!t && b.querySelector('svg.icon') && !name(b)) out.unnamed.push(b.id || b.className);
  }
  for (const s of document.querySelectorAll('svg.icon, use.icon')) {
    if (!vis(s)) continue;
    out.n++;
    const u = s.tagName === 'use' ? s : s.querySelector('use'), r = s.getBoundingClientRect(), bb = u && u.getBBox();
    if (!u || !r.width || !r.height || !bb || !bb.width || !bb.height) out.blank.push(s.getAttribute('class') + ' in ' + (s.parentElement.id || s.parentElement.className.baseVal || s.parentElement.className));
    if (s.tagName === 'svg' && s.getAttribute('aria-hidden') !== 'true' && !(s.getAttribute('role') === 'img' && name(s))) out.hidden.push(s.getAttribute('class'));
  }
  return out;
}"""


def legend_marks_apart(page, sel):
    """#355: at 320 px, each mark (● ◆ ■ ○ ◇ • ▲ ▼) in the legend(s) at sel that a line break parts from the word after
    it: [(the legend's first words, the mark)]. Each is joined to its word by a no-break space. A key drawn as a shape
    (#301: a span holding its svg and its word) is held to the same, as [(…, "shape")]. A legend in a closed
    popover (Labs' Legend, #279) is opened for this, and closed again."""
    size = page.viewport_size
    page.set_viewport_size({"width": 320, "height": 800})
    page.wait_for_timeout(250)
    apart = page.evaluate(r"""sel => {
      const out = [], line = r => r.getClientRects()[0];
      const shut = [...new Set([...document.querySelectorAll(sel)].map(b => b.closest('[popover]')))].filter(p => p && !p.matches(':popover-open'));
      shut.forEach(p => p.showPopover());
      for (const box of document.querySelectorAll(sel)) {
        if (!box.checkVisibility()) continue;
        const w = document.createTreeWalker(box, NodeFilter.SHOW_TEXT);
        for (let n; (n = w.nextNode());) for (const m of n.textContent.matchAll(/[▲▼◆●■○◇•]\s*(?=\S)/g)) {
          const a = document.createRange(), b = document.createRange();
          a.setStart(n, m.index); a.setEnd(n, m.index + 1);
          b.setStart(n, m.index + m[0].length); b.setEnd(n, m.index + m[0].length + 1);
          const ra = line(a), rb = line(b);
          if (!m[0].includes('\u00a0') || !ra || !rb || Math.abs(ra.top - rb.top) > 2) out.push([box.textContent.trim().slice(0, 30), m[0][0]]);
        }
        // a key drawn as a shape (#301): its svg and the first letter of its word on one line
        for (const k of box.querySelectorAll(':scope > span:has(> svg)')) {
          const t = [...k.childNodes].find(n => n.nodeType === 3 && n.textContent.trim()); if (!t) continue;
          const r = document.createRange(); r.setStart(t, 0); r.setEnd(t, 1);
          const a = k.querySelector(':scope > svg').getBoundingClientRect(), b = line(r);
          if (!b || b.top > a.bottom || b.bottom < a.top) out.push([box.textContent.trim().slice(0, 30), 'shape']);
        }
      }
      shut.forEach(p => p.hidePopover());
      return out;
    }""", sel)
    page.set_viewport_size(size)
    page.wait_for_timeout(150)
    return apart


# what icon each place shows on the page, as [place, icon, where] (#399): the top bar and its menus, a phone's tab
# bar, the sidebar, and with palette true the command palette, opened and searched for every page, group and part by
# name. A place is a records tab ("labs"), the bar's own ("add", "dose"), a page ("sources") or a group or part of one
# ("sources/upload"), as groups.js's sgIcon() names them; a link's place is where it goes
ICON_PLACES_JS = r"""async palette => {
  const out = [], page = location.pathname.split('/').pop() || 'index.html', stem = f => f.replace(/\.html$/, '');
  const ico = e => [...(e?.querySelectorAll('svg.icon') || [])].map(s => [...s.classList].find(c => c.startsWith('i-'))?.slice(2)).find(Boolean) || null;
  const ID = {doseLink: 'dose', journalBtn: 'journal', theme: 'theme', logout: 'logout', editTabs: 'settings/sec-tabs', editTabsLink: 'settings/sec-tabs',
    newProfileLink: 'sharing/newProfile', barSearch: 'search', addMenuBtn: 'add', userMenuBtn: 'you', tabMoreBtn: 'more'};
  const place = (file, hash) => {
    if (file === 'guide.html') return 'guide';
    const P = Object.values(SG_PAGES).find(x => x.page === file);
    if (!P) return file + (hash ? '#' + hash : '');
    if (!hash || P.groups.some(x => x.part?.toLowerCase() === hash)) return stem(file);   // (a label's first group, settings.html#you: the page, #991)
    if (SG_ICON[stem(file) + '/' + hash]) return stem(file) + '/' + hash;
    const g = P.groups.find(x => x.id === hash) || P.groups.find(x => x.has.includes(hash) || (x.finds || []).some(f => f[1] === hash));
    return g ? stem(file) + '/' + g.id : stem(file) + '#' + hash;
  };
  const keyOf = x => {
    if (ID[x.id]) return ID[x.id];
    if (x.id && x.id.startsWith('tab-')) return x.id.slice(4);
    const h = x.getAttribute('href');
    if (h == null) return null;
    const u = new URL(h, location.href);
    return place(u.pathname.split('/').pop() || 'index.html', decodeURIComponent(u.hash.slice(1)));
  };
  for (const id of ['profileMenuList', 'addMenuList', 'userMenuList', 'tabMoreList'])
    for (const x of document.querySelectorAll(`#${id} [role^=menuitem]:not([data-pid])`)) out.push([keyOf(x), ico(x), id]);
  for (const id of ['barSearch', 'addMenuBtn', 'userMenuBtn', 'tabMoreBtn']) { const b = document.getElementById(id); if (b && ico(b)) out.push([ID[id], ico(b), 'bar']); }
  for (const a of document.querySelectorAll('header .tabs > a[id^=tab-]')) out.push([a.id.slice(4), ico(a), 'tab bar']);
  for (const a of document.querySelectorAll('.set-nav-list a[data-group]')) out.push([stem(page) + '/' + a.dataset.group, ico(a), 'sidebar']);
  if (!palette) return out;
  SgPalette.open();
  await new Promise(r => setTimeout(r, 1500));   // who you are (Admin's pages, a profile's role)
  const q = document.getElementById('palQ'), titled = new Map();
  for (const [k, P] of Object.entries(SG_PAGES)) {
    titled.set('Page|' + P.title, k);
    for (const g of P.groups) {
      titled.set(P.title + '|' + g.title, k + '/' + g.id);
      for (const [t, id] of g.finds || []) titled.set(`${P.title} › ${g.title}|${t}`, SG_ICON[k + '/' + id] ? k + '/' + id : k + '/' + g.id);
    }
  }
  titled.set('Page|Getting started', 'guide');
  titled.set('Sharing|New share link', 'sharing/links');
  const addKey = new Map([...document.querySelectorAll('#addMenuList [role^=menuitem]')].map(x => [x.textContent.trim(), keyOf(x)]));
  const tabKey = new Map([...document.querySelectorAll('a[id^=tab-]')].map(a => [a.textContent.trim(), a.id.slice(4)]));
  for (const typed of ['', ...new Set([...titled.keys()].map(k => k.split('|')[1]))]) {
    q.value = typed;
    q.dispatchEvent(new Event('input'));
    for (const o of document.querySelectorAll('#palList [role=option]')) {
      const t = o.querySelector('.pal-t').textContent, c = (o.querySelector('.pal-c')?.textContent || '').replace(/^, /, '');
      const k = c === 'Add' ? addKey.get(t) : c === 'Records tab' ? tabKey.get(t) : c === 'Your menu' ? 'theme' : titled.get(c + '|' + t);
      if (k) out.push([k, ico(o), 'palette']);
    }
  }
  document.querySelector('dialog.palette').close();
  return out;
}"""


def icon_audit(page, label):
    """(how many icons are shown, what's wrong with them) on the page as it is (#257)"""
    a = page.evaluate(ICON_AUDIT, [ICON_GLYPHS, TEXT_MARKS])
    if a["blank"]:   # the sprite may still be on its way
        page.wait_for_timeout(500)
        a = page.evaluate(ICON_AUDIT, [ICON_GLYPHS, TEXT_MARKS])
    bad = [f"{label}: a glyph as an icon in “{t}”" for t in a["glyph"]] + [f"{label}: not drawn: {t}" for t in a["blank"]]
    bad += [f"{label}: a symbol in the text, {t}" for t in a["text"]]   # #355
    bad += [f"{label}: an icon neither hidden nor named: {t}" for t in a["hidden"]] + [f"{label}: only an icon, no name: {t}" for t in a["unnamed"]]
    return a["n"], bad


def axe_check(page, label):
    """axe-core's WCAG A and AA rules on the page as it is drawn now (open what is to be checked first: a tab, a menu, a
    dialog). Returns (serious, other): the serious and critical findings, which fail a check, and the moderate and minor
    ones, which are listed; each "label: rule (impact) ×n at selector, … — what's wrong"."""
    if AXE_JS is None:
        return [f"{label}: axe-core isn't installed (pip install --require-hashes -r requirements-dev.txt)"], []
    if not page.evaluate("typeof axe === 'object' && typeof axe.run === 'function'"):
        page.evaluate(AXE_JS)
    # colours as they settle (#343): a control under the pointer eases into its hover look (#256), so a theme just
    # switched would otherwise be measured half way; finite transitions and animations only, at most a second
    page.evaluate("""() => Promise.race([new Promise(r => setTimeout(r, 1000)), Promise.all(document.getAnimations()
        .filter(a => a.effect && a.effect.getTiming().iterations !== Infinity).map(a => a.finished.catch(() => null)))])""")
    serious, other = [], []
    for v in page.evaluate(AXE_RUN, AXE_TAGS):
        (serious if v["impact"] in ("serious", "critical") else other).append(
            f"{label}: {v['id']} ({v['impact']}) ×{v['n']} at {', '.join(v['at'])} — {v['why']}")
    return serious, other


# a page's heading outline (#331): its headings, drawn or there for screen readers only (.vh), as "h2 Key labs", and
# those that skip a level (the first heading counts as following an h0)
OUTLINE_JS = r"""() => {
  const hs = [...document.querySelectorAll('h1, h2, h3, h4, h5, h6, [role=heading]')].filter(h => h.getClientRects().length && !h.closest('[aria-hidden=true], [inert]'));
  const o = hs.map(h => [+(h.getAttribute('aria-level') || h.tagName[1]), h.textContent.trim().replace(/\s+/g, ' ').slice(0, 40)]);
  return {outline: o.map(([l, t]) => `h${l} ${t}`), h1: o.filter(h => h[0] === 1).length,
    skipped: o.filter((h, i) => h[0] > (i ? o[i - 1][0] : 0) + 1).map(([l, t]) => `h${l} ${t}`)};
}"""
# axe-core's landmark rules (#1061, best practice, not WCAG's tags): every landmark rule axe has and region (all that's
# shown in a landmark); the records page had two contentinfo landmarks and its filters outside any
AXE_LANDMARKS = """() => axe.run(document, {runOnly: {type: 'rule', values: axe.getRules().map(r => r.ruleId).filter(id => id === 'region' || id.startsWith('landmark-'))}})
  .then(r => r.violations.map(v => v.id + ' at ' + v.nodes.slice(0, 3).map(n => n.target.join(' ')).join(', ')))"""
# axe-core's empty-table-header (#1075, best practice): a heading over a row's buttons named for screen readers only
AXE_EMPTY_TH = """() => axe.run(document, {runOnly: {type: 'rule', values: ['empty-table-header']}}).then(r => r.violations.flatMap(v => v.nodes.map(n => n.target.join(' '))))"""
AXE_HEADINGS = """() => axe.run(document, {runOnly: {type: 'rule', values: ['heading-order', 'page-has-heading-one', 'empty-heading']}})
  .then(r => r.violations.map(v => v.id + ' at ' + v.nodes.slice(0, 3).map(n => n.target.join(' ')).join(', ')))"""


def heading_outline(page, label):
    """The page's heading outline as it is drawn now, as one line ("label: h1 Costs > h2 …"), and what's wrong with it
    (#331): not exactly one h1, a level skipped, or axe-core's heading rules (heading-order, page-has-heading-one,
    empty-heading: best practice, so not among axe_check's WCAG rules) failing."""
    o = page.evaluate(OUTLINE_JS)
    bad = ([f"{label}: {o['h1']} h1s"] if o["h1"] != 1 else []) + [f"{label}: {h} skips a level" for h in o["skipped"]]
    if AXE_JS is not None:
        if not page.evaluate("typeof axe === 'object' && typeof axe.run === 'function'"):
            page.evaluate(AXE_JS)
        bad += [f"{label}: axe {v}" for v in page.evaluate(AXE_HEADINGS)]
    return f"{label}: " + " > ".join(o["outline"]), bad


# #320: on a phone an account page's table (.acct .tbl) hides its header row, and each cell shows its column's name
# before its value instead (labelCells in util.js, td::before in app.css). Of each such table drawn: where it is, whether
# its headings are hidden, its rows shown, and its cells labelled; and what's wrong: a cell with a value (text or a
# control) under a named column that isn't labelled with that name, or a label where there should be none (the headings
# shown, an empty heading over a row's buttons, a cell spanning columns or an empty one)
CELL_LABELS_JS = r"""() => {
  const out = {tables: [], problems: []};
  for (const t of document.querySelectorAll('main.acct table.tbl')) {
    if (!t.checkVisibility() || !t.tHead) continue;
    const where = ((t.closest('[id]') || {}).id || '') + ' table.' + t.className.trim().split(/\s+/).join('.');
    const hidden = getComputedStyle(t.tHead).display === 'none', heads = [...t.tHead.rows[0].cells].map(h => h.querySelector(':scope > .vh:only-child') ? '' : h.textContent.trim());   // (named for screen readers only: an empty one, #1075)
    let rows = 0, cells = 0;
    for (const r of [...t.tBodies].flatMap(b => [...b.rows]).filter(r => r.checkVisibility())) {
      rows++;
      let col = 0;
      for (const c of r.cells) {
        const head = c.colSpan === 1 && c.tagName === 'TD' ? heads[col] : '';
        col += c.colSpan;
        const value = c.textContent.trim() || (c.querySelector('input, select, textarea, button, img, svg') ? '(a control)' : '');
        const shows = getComputedStyle(c, '::before').content, want = hidden && head && value ? JSON.stringify(head) : 'none';
        if (shows === want || (want === 'none' && shows === 'normal')) { if (want !== 'none') cells++; }
        else out.problems.push(`${where}: "${value.slice(0, 30)}" under "${head}" shows ${shows}, not ${want}`);
      }
    }
    out.tables.push([where, hidden, rows, cells]);
  }
  return out;
}"""


def cell_labels(page, where):
    """#320: the account page's tables drawn now, each [where, headings hidden, rows, cells labelled], and what's wrong
    (CELL_LABELS_JS), with any table whose headings are hidden but still given to screen readers as column headers:
    there the label drawn before each value is the one a screen reader reads, so it isn't heard twice."""
    got = page.evaluate(CELL_LABELS_JS)
    bad = [f"{where}: {p}" for p in got["problems"]]
    tables = page.locator("main.acct table.tbl")
    for i in range(tables.count()):
        t = tables.nth(i)
        if t.is_visible() and t.evaluate("t => !!t.tHead && getComputedStyle(t.tHead).display === 'none'") and "columnheader" in t.aria_snapshot():
            bad.append(f"{where}: table.{t.get_attribute('class')} gives its hidden headings to screen readers too")
    return got["tables"], bad


# a stop of Tab (#202): what has focus, whether it looks any different from when it hasn't (2.4.7), and whether all of
# it is under a fixed or sticky bar (2.4.11). Focus is taken away and given back to compare, which keeps :focus-visible.
FOCUS_STOP_JS = r"""(() => {
  const a = document.activeElement; if (!a || a === document.body || a === document.documentElement) return null;
  const t = (a.getAttribute('aria-label') || a.textContent || a.value || '').replace(/\s+/g, ' ').trim().slice(0, 30);
  const name = a.tagName.toLowerCase() + (a.id ? '#' + a.id : '') + (t ? ` "${t}"` : '');
  const again = window.__fw.has(a); window.__fw.add(a);
  const look = () => { const c = getComputedStyle(a); return [c.outlineStyle !== 'none' && parseFloat(c.outlineWidth) > 0 ? c.outlineStyle + c.outlineWidth + c.outlineColor : '',
    c.boxShadow, c.backgroundColor, c.borderColor, c.color, c.textDecorationLine, c.fill, c.stroke, c.strokeWidth, c.transform].join('|'); };
  const on = look(), r = a.getBoundingClientRect();
  a.blur(); const still = a.matches(':focus-within'), off = look(); a.focus({preventScroll: true});   // still: a date field's calendar button keeps focus
  const bar = e => { for (let p = e; p && p !== document.body; p = p.parentElement) { const cs = getComputedStyle(p); if (cs.position === 'fixed' || cs.position === 'sticky') return true; } return false; };
  const covered = r.width > 4 && r.height > 4 && [[r.left + 2, r.top + 2], [r.right - 2, r.top + 2], [r.left + 2, r.bottom - 2], [r.right - 2, r.bottom - 2], [(r.left + r.right) / 2, (r.top + r.bottom) / 2]]
    .every(([x, y]) => { const e = document.elementFromPoint(x, y); return e && e !== a && !a.contains(e) && !e.contains(a) && !bar(a) && bar(e); });
  return {name, again, shown: still ? on.split('|')[0] !== '' : on !== off, covered};
})()"""


def ring_walk(page, label, stops=12):
    """#310: Tab through a page from its start in light and dark; each stop's outline should be the app's one ring, the
    accent at 2 px (sign-in and setup had the browser's own on their buttons). The problems, and the stops seen."""
    bad, seen = [], []
    for theme in ("light", "dark"):
        page.emulate_media(color_scheme=theme)
        # from the page's start: a focused stand-in there, gone (a blur alone leaves Tab going on from what had focus)
        page.evaluate("(() => { const s = document.createElement('span'); s.tabIndex = -1; document.body.prepend(s); s.focus(); s.remove(); scrollTo(0, 0); })()")
        for _ in range(stops):
            page.keyboard.press("Tab")
            stop = page.evaluate("""(() => { const a = document.activeElement; if (!a || a === document.body) return null;
              const i = document.createElement('i'); i.style.color = 'var(--accent)'; document.body.append(i);
              const accent = getComputedStyle(i).color, c = getComputedStyle(a); i.remove();
              return [a.id || a.tagName.toLowerCase(), c.outlineStyle, c.outlineWidth, c.outlineColor, accent]; })()""")
            if not stop or f"{theme} {stop[0]}" in seen:
                break
            seen.append(f"{theme} {stop[0]}")
            if stop[1:4] != ["solid", "2px", stop[4]]:
                bad.append(f"{label}, {theme}: #{stop[0]} {stop[1]} {stop[2]} {stop[3]} (the accent is {stop[4]})")
    page.emulate_media(color_scheme="no-preference")
    return bad, seen


# a table's wrapper (#335, #340): each drawn now (of those the selector given matches, every .tablewrap by default),
# as [whether it scrolls, sideways or down, its name, its tabIndex, its role, the id it's in]. One that scrolls must
# take focus and have a name, a region, so a keyboard can reach what's out of sight and a screen reader says what it
# is; one that doesn't must be neither, no tab stop and no landmark (scroll_table_faults)
SCROLL_TABLES_JS = r"""sel => [...document.querySelectorAll(sel || '.tablewrap')]
  .filter(w => w.checkVisibility())
  .map(w => [w.scrollWidth > w.clientWidth + 1 || w.scrollHeight > w.clientHeight + 1,
             w.getAttribute('aria-label') || (w.getAttribute('aria-labelledby') && document.getElementById(w.getAttribute('aria-labelledby'))?.textContent) || '',
             w.tabIndex, w.getAttribute('role'), (w.closest('[id]') || {}).id || ''])"""


def scroll_table_faults(wraps):
    """SCROLL_TABLES_JS's rows (each with what it was on put first) that are wrong: scrolling but not a named region in
    the Tab order, or not scrolling but a tab stop, a region or named (#340, #347)"""
    return [w for w in wraps if ((w[3] != 0 or not w[2].strip() or w[4] != "region") if w[1] else (w[3] >= 0 or w[4] == "region" or w[2].strip()))]


# a field's look (#332), in light and dark (the theme set on the page, then put back): its background, edge and corner.
# Sign-in's and setup's fields are compared with one on Account
FIELD_LOOK_JS = r"""sel => Object.fromEntries(['light', 'dark'].map(t => {
  const r = document.documentElement, was = r.dataset.theme; r.dataset.theme = t;
  const c = getComputedStyle(document.querySelector(sel));
  const look = [c.backgroundColor, `${c.borderTopWidth} ${c.borderTopStyle} ${c.borderTopColor}`, c.borderTopLeftRadius];
  if (was) r.dataset.theme = was; else delete r.dataset.theme;
  return [t, look]; }))"""


def focus_walk(page, label, back=False, stops=60):
    """Tab (or Shift+Tab from the page's end) through up to `stops` controls; the problems found, each "label: control …".
    A stop that shows no change when focused, or lies wholly under a sticky or fixed bar, is a problem."""
    if back:
        page.evaluate("window.scrollTo(0, document.documentElement.scrollHeight); (f => { if (f) { f.tabIndex = -1; f.focus(); } })(document.querySelector('.pagefoot, footer'))")
    else:
        page.evaluate("document.activeElement && document.activeElement.blur(); window.scrollTo(0, 0)")
    page.evaluate("window.__fw = new WeakSet()")
    out = []
    for _ in range(stops):
        page.keyboard.press("Shift+Tab" if back else "Tab")
        s = page.evaluate(FOCUS_STOP_JS)
        if not s:
            continue
        if s["again"]:   # round to the start
            break
        if not s["shown"]:
            out.append(f"{label}: {s['name']} shows no sign of focus")
        if s["covered"]:
            out.append(f"{label}: {s['name']} has focus under a sticky bar")
    return out


# #651: what has focus on Labs, after the browser has brought it into view, against Labs' two pinned parts: the event
# track while it's stuck and the stack's time axis. "out" once focus has left Labs; else the control's name and which of
# them is over any of its middle and corners, or null. One taller than the room between them, filling it, can't be clear
UNDER_PINNED_JS = r"""() => {
  const a = document.activeElement; if (!a || a === document.body || !a.closest('#view-labs')) return 'out';
  const r = a.getBoundingClientRect(); if (!r.width || !r.height) return null;
  const track = document.getElementById('evTrack'), foot = document.querySelector('#charts > .ck-foot');
  const t = track?.classList.contains('stuck') && !track.contains(a) ? track.getBoundingClientRect() : null, f = foot?.getBoundingClientRect();
  const top = t && t.bottom > 0 ? t.bottom : 0, bot = f && f.top < innerHeight ? f.top : innerHeight;
  if (r.height > bot - top && r.top <= top + 1 && r.bottom >= bot - 1) return null;
  const under = [[(r.left + r.right) / 2, (r.top + r.bottom) / 2], [r.left + 2, r.top + 2], [r.right - 2, r.top + 2], [r.left + 2, r.bottom - 2], [r.right - 2, r.bottom - 2]].map(([x, y]) => {
    const e = y >= 0 && y < innerHeight && x >= 0 && x < innerWidth && document.elementFromPoint(x, y);
    return !e || a === e || a.contains(e) || e.contains(a) ? '' : e.closest('#evTrack') ? 'the track' : e.closest('.ck-foot') ? 'the axis' : ''; }).filter(Boolean);
  return under.length ? `${a.tagName.toLowerCase()} "${(a.getAttribute('aria-label') || a.textContent).trim().slice(0, 30)}" under ${[...new Set(under)].join(' and ')}, ${Math.round(r.top)}–${Math.round(r.bottom)} of ${innerHeight}` : null; }"""


def labs_walk(pg, back=False, limit=160):
    """#651: Tab (or Shift+Tab from its last control) through Labs, as a keyboard user would, until focus leaves it or
    comes round again: (how many took focus, [each wholly or partly under the event track or the stack's axis])"""
    pg.evaluate("""b => { window.__lw = new Set(); if (!b) { scrollTo(0, 0); return document.querySelector('#labsView button').focus(); }
      [...document.querySelectorAll('#view-labs :is(button, input, select, a[href], [tabindex]:not([tabindex="-1"]))')].filter(e => e.checkVisibility() && !e.disabled).at(-1).focus(); }""", back)
    n, bad = 0, []
    for _ in range(limit):
        pg.keyboard.press("Shift+Tab" if back else "Tab")
        pg.wait_for_timeout(40)
        if pg.evaluate("(() => { const a = document.activeElement; if (__lw.has(a)) return true; __lw.add(a); return false; })()"):
            break
        got = pg.evaluate(UNDER_PINNED_JS)
        if got == "out":
            break
        n += 1
        if got:
            bad.append(got)
    return n, bad


# the labels on a time chart (#312): of each chart matching the selector (an argument) that is drawn, its aria-label,
# whether it has milestones, how many as a faint line (#298), and its milestone labels ([text, the full names and dates in its title]); how many
# procedures are named; and what's wrong: a label running past its plot's left or right edge, or a procedure's or
# imaging's mark (● ■) on a label's text
CHART_LABELS_JS = r"""sel => {
  const out = {charts: [], ev: 0, problems: []};
  for (const svg of document.querySelectorAll(sel)) {
    const g = svg._geom;
    if (!g || !svg.checkVisibility() || !svg.getBoundingClientRect().width) continue;
    const said = svg.getAttribute('aria-label') || '', name = said.split(/[:,]/)[0], heads = [...svg.querySelectorAll('.evhead')].map(h => h.getBBox());
    const c = {said, marked: !!svg.querySelector('.msmark'), faint: svg.querySelectorAll('.msmark.faint').length, ms: []}; out.charts.push(c);
    for (const t of svg.querySelectorAll('.mslabel, .evlabel')) {
      const b = t.getBBox(), text = t.firstChild.textContent;
      if (t.classList.contains('mslabel')) c.ms.push([text, t.querySelector('title')?.textContent || '']); else out.ev++;
      if (b.x < g.L - .5 || b.x + b.width > g.R + .5)
        out.problems.push(`${name}: "${text}" runs past the plot (${Math.round(b.x)} to ${Math.round(b.x + b.width)}, plot ${Math.round(g.L)} to ${Math.round(g.R)})`);
      if (heads.some(h => h.x < b.x + b.width && h.x + h.width > b.x && h.y < b.y + b.height && h.y + h.height > b.y))
        out.problems.push(`${name}: a mark lies on "${text}"`);
    }
  }
  return out;
}"""

# Body and activity's charts in their forms (#298): {hr: the heart rate chart's day band (0 or 1), its highest tick and whether
# the toggle is there, comp: body fat's and lean mass's dots, their line's points and the share of them on a dot, steps:
# its bars' fill opacity, its average's stroke and its target lines, sleep: over 150 days, a line, the stages' paths all
# under the plot, how many, the narrowest gap between bars and between a stack's first two parts, tiles: the changes,
# bmi: [heights on file, BMI headings, the hint's start]}
FORMS298_JS = r"""() => {
  const svgOf = k => document.querySelector(k + ' svg.ck'), g = s => s._geom;
  const rects = d => [...(d || '').matchAll(/M([\d.-]+),([\d.-]+)h([\d.-]+)v([\d.-]+)/g)].map(m => m.slice(1).map(Number));
  const ticks = s => [...s.querySelectorAll('text[text-anchor=end]')].filter(t => +t.getAttribute('x') < g(s).L).map(t => parseFloat(t.textContent));
  const out = {};
  // heart rate: resting on its own scale, no band; the day's band a toggle away
  const hr = svgOf('#h-heart');
  out.hr = {band: hr.querySelectorAll('path[opacity]:not([stroke])').length, top: Math.max(...ticks(hr)), toggle: !!document.getElementById('hrDay')};
  // body composition: dots under a 14-day average, the line not through every dot
  out.comp = [...document.querySelectorAll('#h-body .ov-cols svg.ck')].map(s => {
    const line = s.querySelector('path[stroke]:not(.refedge)'), dots = [...s.querySelectorAll('circle')].map(c => [+c.getAttribute('cx'), +c.getAttribute('cy')]);
    const vs = [...line.getAttribute('d').matchAll(/[ML]([\d.-]+),([\d.-]+)/g)].map(m => [+m[1], +m[2]]);
    const on = vs.filter(([x, y]) => dots.some(([cx, cy]) => Math.abs(cx - x) < .6 && Math.abs(cy - y) < .6)).length;
    return {dots: dots.length, line: vs.length, on: +(on / vs.length).toFixed(2)};
  });
  // steps: a pale tint under the ink of its average
  const st = svgOf('#h-activity'), bars = st.querySelector('path[fill="var(--measure)"]'), avg = st.querySelector('path[stroke]');
  out.steps = {tint: bars && +bars.getAttribute('fill-opacity'), avg: avg && avg.getAttribute('stroke'), target: st.querySelectorAll('.tgt-edge').length};
  // sleep: a weekly line with the stages' strip under the plot over 150 days; bars with 2 px gaps under
  const sl = svgOf('#h-sleep'), G = g(sl), ps = [...sl.querySelectorAll('path[fill^="var(--seq"]')];
  const all = ps.map(p => rects(p.getAttribute('d')));
  const xs = [...new Set(all.flat().map(r => r[0]))].sort((a, b) => a - b), w = all.flat()[0]?.[2];
  let gaps = [];
  for (let i = 1; i < xs.length; i++) gaps.push(+(xs[i] - xs[i - 1] - w).toFixed(1));
  // a stack's parts: the second's foot 2 px over the first's top
  const deep = new Map(all[0]?.map(r => [r[0], r[1]]) || []), seg = (all[1] || []).filter(r => deep.has(r[0])).map(r => +(deep.get(r[0]) - (r[1] + r[3])).toFixed(1));
  out.sleep = {long: hRange()[1] - hRange()[0] > 150 * DAY, line: !!sl.querySelector('path[stroke]:not(.refedge)'), strip: ps.length && all.flat().every(r => r[1] > G.B),
    bars: ps.length, minGap: gaps.length ? Math.min(...gaps) : null, minSeg: seg.length ? Math.min(...seg) : null};
  // the tiles' changes: ↑ / ↓ or "no change", never ▲ / ▼ or a sign
  out.tiles = [...document.querySelectorAll('#view-health .tile .delta')].map(d => d.textContent).filter(t => / (this|previous) period/.test(t));
  // no empty BMI block
  out.bmi = [personOf().heights.length, document.querySelectorAll('#h-body .bmi h4').length, document.querySelector('#h-body .bmi .hint')?.textContent.slice(0, 5)];
  return out;
}"""

# Body and activity's charts against their tables (#659), in the period: of every chart (svg.ck), the count and first date
# its name says, and the points Home, the right arrow and End reach, against the rows of its card's table with a value
# in its column, the table drawn whole for this (H_PAGE), oldest first: as many, each row's date the point's (a day, a
# time, or "Week of" its Monday). A chart of home readings by week whose table lists each one (blood pressure, oxygen,
# respiratory rate, VO2 max over 150 days) counts weeks (#721: its weeks were "readings"): "20 weeks of home readings
# (161 readings) and 4 readings at visits", the weeks and the readings drawn one by one the points the keys reach, what
# the weeks average and those readings its table's rows. {charts: [name, its table's rows], problems}. Async: the
# charts are drawn in a frame. test_performance.py reads it to check the ten years the same way
NAV659_JS = r"""async () => {
  const frames = () => new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r))), had = [...state.tables], page = H_PAGE, out = {charts: [], problems: []};
  state.tables.clear(); renderHealth(); await frames();
  const charts = [...document.querySelectorAll('#view-health svg.ck')].map(svg => ({svg, card: '#' + svg.closest('.card').id, said: svg.getAttribute('aria-label'), ts: [],
    weekly: /^[^:]*(, weekly|by week):/.test(svg.getAttribute('aria-label'))}));   // home readings by week, each listed in the table
  for (const c of charts) {
    const key = k => c.svg.onkeydown({key: k, preventDefault() {}, stopPropagation() {}});
    for (key('Home'); c.svg._kt != null && c.ts.at(-1) !== c.svg._kt; key('ArrowRight')) c.ts.push(c.svg._kt);
    key('End');
    c.end = c.svg._kt;
    key('Escape');
  }
  H_PAGE = 1e6; for (const c of charts) state.tables.add(c.card);
  renderHealth(); await frames();
  const tables = {};
  for (const c of charts) { const t = [...document.querySelectorAll(c.card + ' table.data')].at(-1);
    if (t) tables[c.card] = {heads: [...t.tHead.rows[0].cells].map(x => x.textContent), rows: [...t.tBodies[0].rows].map(r => [...r.cells].map(x => x.textContent))}; }
  H_PAGE = page; state.tables.clear(); had.forEach(k => state.tables.add(k)); renderHealth(); await frames();
  const COL = [[/^Weight/, /^Weight/], [/^Body fat/, /^Body fat/], [/^Lean mass/, /^Lean mass/], [/^BMI/, /^BMI/], [/^Heart rate variability/, /variability/],
    [/^Heart rate zones/, null], [/^Heart rate/, hState.hrDay ? /^Average/ : /^Resting/], [/^Steps/, /^Steps/]];
  const says = t => [fmtD(t), fmtDT(t), 'Week of ' + fmtD(t - 3 * DAY)], num = v => +(v || '0').replace(/,/g, '');
  for (const c of charts) {
    const name = c.said.split(':')[0], tb = tables[c.card], col = (COL.find(([n]) => n.test(name)) || [])[1], ci = col ? tb?.heads.findIndex(h => col.test(h)) : 0;
    if (c.weekly) {   // weeks, what they average and the readings one by one (#721)
      const rows = tb ? tb.rows.length : 0, w = /: ([\d,]+) weeks? of [^(]+ \(([\d,]+) \w+\)(?:(?:,| and) ([\d,]+) readings? at home)?(?: and ([\d,]+) readings? at visits)? from (.+?) to .+?\. /.exec(c.said);
      out.charts.push([name, rows]);
      if (!w) { if (rows || c.ts.length) out.problems.push(`${name}: "${c.said.split('. ')[0]}" counts no weeks, its table ${rows} rows`); continue; }
      const [weeks, days, home, visits] = w.slice(1, 5).map(num);
      if (days + home + visits !== rows) out.problems.push(`${name}: "${c.said.split('. ')[0]}", its table ${rows} rows`);
      if (weeks + home + visits !== c.ts.length || w[5] !== fmtD(c.ts[0]) || c.end !== c.ts.at(-1))
        out.problems.push(`${name}: "${c.said.split('. ')[0]}", the keys reach ${c.ts.length}${c.ts.length ? ' from ' + fmtD(c.ts[0]) : ''}, End ${c.end === c.ts.at(-1) ? 'the last' : 'another'}`);
      continue;
    }
    if (!tb || ci < 0) { out.problems.push(`${name}: no table to compare`); continue; }
    const rows = tb.rows.filter(r => !col || r[ci].trim()).map(r => r[0]).reverse(), m = /: (\d+) .+? (?:from (.+?) to .+?|in this period)\. /.exec(c.said);
    out.charts.push([name, rows.length]);
    if (!m || +m[1] !== rows.length || (rows.length && m[2] !== fmtD(c.ts[0]))) out.problems.push(`${name}: "${c.said.split('. ')[0]}", its table ${rows.length} rows from ${rows[0]}`);
    if (c.ts.length !== rows.length || rows.some((r, i) => !says(c.ts[i]).includes(r)) || c.end !== c.ts.at(-1))
      out.problems.push(`${name}: the keys reach ${c.ts.length}${c.ts.length ? ' from ' + fmtD(c.ts[0]) : ''}, End ${c.end === c.ts.at(-1) ? 'the last' : 'another'}, of its table's ${rows.length} from ${rows[0]}`);
  }
  return out;
}"""

# Body and activity's All against 2 years (#721): every card on Table, drawn whole (H_PAGE), at "2y" and then "All": each
# row of a table by date (its first two cells) on 2 years is on All too, and a tile's count (readings, sessions, nights) is
# no smaller. All spanned the phone's and the scale's days only, so a weight or the vitals taken at a visit before the
# watch's first day were on 2 years and not on All. {rows: {card: [2 years' rows, All's]}, problems}. Async; the period
# and the cards' views put back. test_performance.py reads it to check the ten years the same way
ALL721_JS = r"""async () => {
  const frames = () => new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r))), had = [...state.tables], page = H_PAGE, was = [state.preset, state.from, state.to];
  const out = {rows: {}, problems: []}, count = t => { const m = /([\d,]+) (?:meter )?(reading|session|night)s?\b/.exec(t); return m ? [m[2], +m[1].replace(/,/g, '')] : null; };
  const read = async p => {
    applyPreset(p); H_PAGE = 1e6;
    for (const s of document.querySelectorAll('#view-health .view-seg')) state.tables.add(s.dataset.key);
    renderHealth(); await frames();
    const t = {};
    for (const s of document.querySelectorAll('#view-health .view-seg')) t[s.dataset.key] = [...document.querySelectorAll(s.dataset.key + ' table.data')]
      .filter(x => /^(Date|Week|Night)/.test(x.tHead.rows[0].cells[0].textContent)).flatMap(x => [...x.tBodies[0].rows].map(r => [...r.cells].slice(0, 2).map(c => c.textContent).join(' | ')));
    const words = x => [x.querySelector('.val')?.firstChild?.textContent, x.querySelector('.val small')?.textContent, x.querySelector('.delta')?.textContent].join(' ');
    return {t, tiles: Object.fromEntries([...document.querySelectorAll('#view-health .tile')].map(x => [x.querySelector('.lbl').textContent, count(words(x))]))};
  };
  const lp = lastPeriod, two = await read('2y'), all = await read('all');
  for (const [k, rows] of Object.entries(two.t)) {
    const have = new Set(all.t[k] || []), miss = rows.filter(r => !have.has(r));
    out.rows[k] = [rows.length, (all.t[k] || []).length];
    if (miss.length) out.problems.push(`${k}: ${miss.length} of 2 years' rows not on All, as "${miss[0]}"`);
  }
  for (const [n, c] of Object.entries(two.tiles)) if (c && !(all.tiles[n] && all.tiles[n][1] >= c[1])) out.problems.push(`the ${n} tile: ${c[1]} ${c[0]}s on 2 years, ${all.tiles[n] ? all.tiles[n][1] : 'none'} on All`);
  H_PAGE = page; state.tables.clear(); had.forEach(k => state.tables.add(k)); [state.preset, state.from, state.to] = was; lastPeriod = lp; renderAll(); await frames();
  return out;
}"""

# Body and activity's controls that draw the tab again (#720): each card's Chart | Table and its options (toggle chips),
# each pressed from the middle of the window as Enter or Space does (a click with focus on it), and pressed back. Its
# charts are drawn a frame after the tab: keepFocus (store.js) measured them as placeholders 150 px tall, and as they
# took their heights the control went down past the window's foot, or under the phone's tab bar. After both frames, the
# control has focus and is wholly in sight, clear of the top bar and the tab bar (html's scroll-padding, its box read).
# #766: and where it was, 1.5 px at most, as the press is answered and once the charts are drawn: keepFocus brought it
# into sight on the placeholders' layout, so it went to the window's foot (326 px on the ten years at 412 px) and stayed,
# or showed there a frame; in sight, it was left where the charts above had moved it.
# {n: presses, problems}. Async. test_performance.py reads it to check the ten years the same way
FOCUS720_JS = r"""async () => {
  const frames = () => new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r))), out = {n: 0, problems: []};
  const seen = e => { const r = e.getBoundingClientRect(), cs = getComputedStyle(document.documentElement);
    return r.top >= (parseFloat(cs.scrollPaddingTop) || 0) - 1 && r.bottom <= innerHeight - (parseFloat(cs.scrollPaddingBottom) || 0) + 1; };
  const seg = k => document.querySelector(`#view-health .view-seg[data-key="${k}"]`);
  const chip = t => [...document.querySelectorAll('#view-health .card label.toggle')].find(l => l.textContent.trim() === t);
  const all = [...[...document.querySelectorAll('#view-health .view-seg')].map(s => ['seg', s.dataset.key]),
    ...[...document.querySelectorAll('#view-health .card label.toggle')].map(l => ['chip', l.textContent.trim()])];
  for (const [k, n] of all) for (const back of ['', ', back']) {
    const c = k === 'seg' ? seg(n)?.querySelector('button:not([aria-pressed=true])') : chip(n)?.querySelector('input');
    if (!c) { out.problems.push(`${n}${back}: not there`); break; }
    c.scrollIntoView({block: 'center'}); await frames();
    c.focus(); const t0 = c.getBoundingClientRect().top; c.click(); const t1 = document.activeElement.getBoundingClientRect().top; await frames(); await frames();
    const a = document.activeElement, r = a.getBoundingClientRect();
    out.n++;
    if (!(k === 'seg' ? a.closest('.view-seg') === seg(n) && a.getAttribute('aria-pressed') === 'true' : a.closest('label') === chip(n)))
      out.problems.push(`${n}${back}: focus on ${a === document.body ? 'the page' : a.tagName + ' ' + a.textContent.trim().slice(0, 30)}`);
    else if (!seen(a)) out.problems.push(`${n}${back}: at ${Math.round(r.top)} to ${Math.round(r.bottom)} in a window ${innerHeight} px tall, not wholly in sight`);
    else if (Math.abs(t1 - t0) > 1.5 || Math.abs(r.top - t0) > 1.5) out.problems.push(`${n}${back}: at ${Math.round(t0)}, then ${Math.round(t1)} as it's drawn and ${Math.round(r.top)} once its charts are (#766)`);
  }
  return out;
}"""
# what has focus (#720): [its name, wholly in sight clear of the top bar and the tab bar, its top, its foot]
FOCUSED720_JS = r"""() => { const a = document.activeElement, r = a.getBoundingClientRect(), cs = getComputedStyle(document.documentElement);
  return [a === document.body ? 'the page' : `${a.tagName} ${(a.getAttribute('aria-label') || a.textContent).split(':')[0].trim().slice(0, 40)}`,
    r.top >= (parseFloat(cs.scrollPaddingTop) || 0) - 1 && r.bottom <= innerHeight - (parseFloat(cs.scrollPaddingBottom) || 0) + 1, Math.round(r.top), Math.round(r.bottom)]; }"""
# every chart on Body and activity, in turn, given focus in the middle of the window (#720)
BODY_CHART720_JS = r"""i => { const s = [...document.querySelectorAll('#view-health svg[role=application]')].filter(s => s.checkVisibility())[i];
  if (s) { s.scrollIntoView({block: 'center'}); s.focus({preventScroll: true}); } return !!s; }"""

# a chart's keyboard steps said (#913): the shown chart sel (the nth), focused in the middle of the window, stepped Home, →,
# →, End and ←, the page's status line (announce, util.js: #sgStatus) emptied before each and read 200 ms after (its words
# are written 60 ms after they're given). [what's wrong]: a step that said nothing, one that said what the stop before it
# said though it moved, and one whose words aren't its tooltip's, what's shown read out (where it shows one; the event
# track says the kind first and which of how many: "Milestone: Diagnosis, Apr 14, 2025. 3 of 11.", tip False)
STEP913_JS = r"""([sel, n]) => { const s = [...document.querySelectorAll(sel)].filter(s => s.checkVisibility())[n];
  if (!s) return false; s.scrollIntoView({block: 'center'}); s.focus({preventScroll: true}); return document.activeElement === s; }"""
SAID913_JS = r"""() => { const t = document.getElementById('tip'), norm = x => x.replace(/[▲▼◆]/g, '').replace(/[^\p{L}\p{N}]+/gu, '');
  const said = document.getElementById('sgStatus').textContent;
  return [said, String(document.activeElement._kt), getComputedStyle(t).display === 'none' ? null : norm(t.textContent) === norm(said)]; }"""


def steps913(page, where, sel, n=0, tip=True):
    if not page.evaluate(STEP913_JS, [sel, n]):
        return [f"{where}: not focused"]
    out, was = [], None
    for k in ("Home", "ArrowRight", "ArrowRight", "End", "ArrowLeft"):
        page.evaluate("document.getElementById('sgStatus').textContent = ''")
        page.keyboard.press(k)
        page.wait_for_timeout(200)
        said, kt, same = page.evaluate(SAID913_JS)
        if not said.strip():
            out.append(f"{where}, {k}: nothing said")
        elif was and kt != was[1] and said == was[0]:
            out.append(f"{where}, {k}: “{said[:60]}” said again at another stop")
        elif same is False if tip else not re.search(r"\. \d+ of \d+\.$", said):
            out.append(f"{where}, {k}: said “{said[:80]}”, not {'its tooltip' if tip else 'which of how many'}")
        was = (said, kt)
    page.keyboard.press("Escape")
    return out

# Labs' event track (#294, event-track.js): {items: the events it marks, named: its names, folded: how many a "+N" counts,
# marks, rows: rows of names, layers: rows under them, stuck: under the top bar, inCharts: any event, name or layer's mark
# drawn in a chart, problems: a name past the plot, on another or with a leader through it, an event neither named nor
# counted, a mark too many or too few, a chart whose aria-label doesn't name the milestones}
TRACK_JS = r"""() => {
  const out = {items: 0, named: 0, folded: 0, marks: 0, rows: 0, layers: 0, stuck: null, problems: [],
    inCharts: document.querySelectorAll('#charts .chart svg :is(.evhead, .evlabel, .mslabel, .medbar, .medfill, .jmark, .jmood, .cymark, .dosemark)').length};
  const card = document.getElementById('evTrack'), svg = card && card.querySelector('svg.ev-svg');
  if (!svg) return out;
  const g = svg._geom, items = trackItems();
  Object.assign(out, {items: items.length, stuck: card.classList.contains('stuck') && getComputedStyle(card).position === 'sticky',
    marks: svg.querySelectorAll('.evhead, .msflag-head').length, layers: trackLayers().length});
  const names = [...svg.querySelectorAll('.ev-name')].map(t => ({b: t.getBBox(), text: t.textContent, y: t.getAttribute('y')}));
  out.rows = new Set(names.map(n => n.y)).size;
  for (const n of names) {
    const m = n.text.match(/ \+(\d+)$/); out.named++; out.folded += m ? +m[1] : 0;
    if (n.b.x < g.L - .5 || n.b.x + n.b.width > g.R + .5) out.problems.push(`"${n.text}" runs past the plot`);
  }
  names.forEach((p, i) => names.slice(i + 1).forEach(q => {
    if (p.b.x < q.b.x + q.b.width && q.b.x < p.b.x + p.b.width && p.b.y < q.b.y + q.b.height && q.b.y < p.b.y + p.b.height) out.problems.push(`"${p.text}" and "${q.text}" overlap`); }));
  for (const l of svg.querySelectorAll('line.evlead, line.msflag')) {
    const lx = +l.getAttribute('x1'), y1 = +l.getAttribute('y1') + 1, y2 = +l.getAttribute('y2');
    for (const n of names) if (lx > n.b.x && lx < n.b.x + n.b.width && y1 < n.b.y + n.b.height && y2 > n.b.y) out.problems.push(`a leader runs through "${n.text}"`);
  }
  if (out.named + out.folded !== out.items) out.problems.push(`${out.named} names and ${out.folded} under "+N" for ${out.items} events`);
  if (out.marks !== out.items) out.problems.push(`${out.marks} marks for ${out.items} events`);
  const ms = MILESTONES.filter(m => dayTs(m.date) >= state.from && dayTs(m.date) <= state.to).map(m => m.label);
  for (const c of document.querySelectorAll('#charts .chart svg.ck'))
    if (!ms.every(m => c.getAttribute('aria-label').includes(m))) out.problems.push(`${c.getAttribute('aria-label').split(':')[0]}: its aria-label doesn't name every milestone`);
  return out;
}"""

# a kit chart's time axis (#291, chartkit.js): of each drawn chart matching the selector (an argument), its labels under
# the plot (below _geom.B: the finer row, and the coarser row's .ck-yr), and what's wrong with them: two in a row that
# overlap, one sticking out of its chart, or a month written as it would read as a day ("Sep 26", #561)
CHART_AXIS_JS = r"""sel => {
  const out = {charts: 0, rows: [], problems: []};
  for (const svg of document.querySelectorAll(sel)) {
    const g = svg._geom, r = svg.getBoundingClientRect();
    if (!g || g.B == null || !svg.checkVisibility() || !r.width) continue;
    out.charts++;
    const name = (svg.getAttribute('aria-label') || '').split(/[:,]/)[0], rows = new Map();
    for (const t of svg.querySelectorAll('text')) {
      if (+t.getAttribute('y') <= g.B || t.getAttribute('text-anchor') === 'end' || (t.getAttribute('class') && !t.classList.contains('ck-yr'))) continue;   // not a value's label by its gridline
      const b = t.getBoundingClientRect(), y = t.getAttribute('y');
      if (!rows.has(y)) rows.set(y, []);
      rows.get(y).push([b.left, b.right, t.textContent]);
      if (b.left < r.left - .5 || b.right > r.right + .5) out.problems.push(`${name}: "${t.textContent}" sticks out of its chart`);
      if (/^[A-Z][a-z]{2} \d{1,2}$/.test(t.textContent)) out.problems.push(`${name}: "${t.textContent}" reads as a day`);
    }
    for (const row of rows.values()) {
      row.sort((p, q) => p[0] - q[0]);
      row.forEach((p, i) => { if (i && p[0] < row[i - 1][1] - .5) out.problems.push(`${name}: "${row[i - 1][2]}" and "${p[2]}" overlap`); });
    }
    out.rows.push([...rows.values()].map(row => row.map(p => p[2])));
  }
  return out;
}"""

# the value axes' numbers (#654): GRID654_JS(true) has the kit's ckGrid (chartkit.js) mark each gridline it draws with its
# value (data-v) and its axis (data-axis, one a call), and GRID654_JS(false) puts ckGrid back as it was. AXIS654_JS(sel)
# then reads each marked gridline's label (the text drawn after it) in the charts matching sel as a number ("$2.5K",
# "92.5%", "7.5k", "8h", "−25%"): {lines: how many, problems: a label that isn't its gridline's value as it is, an axis
# saying one number twice}. test_performance.py reads both to check the ten years the same way
GRID654_JS = r"""on => {
  if (!on) { if (window._grid654) { ckGrid = window._grid654; delete window._grid654; } return; }
  if (window._grid654) return;
  const was = window._grid654 = ckGrid; let n = 0;
  ckGrid = (g, y, vals, ...rest) => { const at = g.length; was(g, y, vals, ...rest); n++;
    g.slice(at).filter(e => e.matches('line.gridline')).forEach((e, i) => { e.dataset.v = vals[i]; e.dataset.axis = n; }); };
}"""
AXIS654_JS = r"""sel => {
  const out = {lines: 0, problems: []}, num = s => { const m = /^\$?([−-]?)([\d,]*\.?\d+)([kKM]?)[%hm]?$/.exec(s.trim());
    return m ? (m[1] ? -1 : 1) * parseFloat(m[2].replace(/,/g, '')) * ({k: 1e3, K: 1e3, M: 1e6}[m[3]] || 1) : NaN; };
  for (const svg of document.querySelectorAll(sel)) {
    if (!svg.checkVisibility()) continue;
    const name = `${svg.closest('[id]')?.id} ${(svg.getAttribute('aria-label') || '').split(/[:.]/)[0]}`, axes = new Map();
    for (const l of svg.querySelectorAll('line.gridline[data-v]')) {
      const said = l.nextElementSibling?.textContent || '', v = +l.dataset.v;
      out.lines++;
      if (!(Math.abs(num(said) - v) <= 1e-9 * Math.max(1, Math.abs(v)))) out.problems.push(`${name}: the gridline at ${v} says "${said}"`);
      if (!axes.has(l.dataset.axis)) axes.set(l.dataset.axis, []);
      axes.get(l.dataset.axis).push(said);
    }
    for (const a of axes.values()) if (new Set(a).size < a.length) out.problems.push(`${name}: an axis says ${a.join(', ')}`);
  }
  return out;
}"""

# what a chart draws in the accent (#334): of each drawn chart matching the selector (an argument), every element whose
# computed fill or stroke is the accent's colour (read from an element that uses --accent), and how many milestone rules,
# milestone labels and cursors were looked at, so the check can't pass on charts with none. A cursor is hidden until a
# point is hovered or picked by key, and styled all the same, so it's read hidden
CHART_ACCENT_JS = r"""sel => {
  const i = document.createElement('i'); i.style.color = 'var(--accent)'; document.body.append(i);
  const accent = getComputedStyle(i).color; i.remove();
  const out = {accent, bad: [], rules: 0, labels: 0, cursors: 0};
  for (const svg of document.querySelectorAll(sel)) {
    if (!svg.checkVisibility() || !svg.getBoundingClientRect().width) continue;
    out.rules += svg.querySelectorAll('.msmark').length; out.labels += svg.querySelectorAll('.mslabel').length;
    out.cursors += svg.querySelectorAll('.cross, .ecg-cursor').length;
    for (const e of svg.querySelectorAll('*')) {
      const c = getComputedStyle(e);
      if (c.fill === accent || c.stroke === accent)
        out.bad.push(`${(svg.getAttribute('aria-label') || svg.id || sel).split(/[:,]/)[0]}: <${e.tagName} class="${e.getAttribute('class') || ''}"> in the accent`);
    }
  }
  return out;
}"""


# a tab opened for the tile checks (#330, #339, #351), from [tab, period]: "costs" is Costs' Claims and "costs-paid" its
# What you paid, each with its More figures open, so every figure is measured (#278)
TILE_TAB_JS = """([t, p]) => { if (p) setPeriod(p);
  if (t.startsWith('costs')) Object.assign(costState, {view: t === 'costs' ? 'claims' : 'paid', more: true}); switchTab(t.split('-')[0]); }"""


# a unit as the pages say it (#1103: util.js unitSaid, server/units.py said, test_units holding them alike), for what's
# expected of a page in a unit as reported ("10*3/uL" is 10³/µL); and a dict keyed (lab, unit, ...) keyed so
def unit_said(u):
    from server import units
    return units.said(u)


def said_keys(d):
    return {(k[0], unit_said(k[1]), *k[2:]): v for k, v in d.items()}


# the sparklines under root (#299), each as chartkit.js ckSpark draws it: how many points its line has (0: none), its
# marks, its band's tallest step in the plot's 100 (the band is the middle 60% at most: the scale is set by it), its
# first mark's width over its height (1 for a dot not stretched); and how many other pictures are in its place (old)
SPARK299_JS = r"""root => ({sparks: [...document.querySelectorAll(root + ' svg.spark')].map(s => {
  const plot = s.querySelector(':scope > svg[preserveAspectRatio=none]'), line = plot?.querySelector('path:not([class])');
  const marks = [...s.querySelectorAll(':scope > circle, :scope > svg:not([viewBox]) > path')], m = marks[0]?.getBoundingClientRect();
  return {pts: line ? line.getAttribute('d').split('L').length : 0, marks: marks.length,
    band: Math.max(0, ...[...(plot?.querySelectorAll('.refband') || [])].map(r => +r.getAttribute('height'))), round: m ? m.width / m.height : null};
}), old: document.querySelectorAll(`${root} :is(td, .tile) > svg:not(.spark, .icon)`).length})"""
# … and whether they're all right: a line of three points or more with its latest's mark, or no line and that mark alone
spark299_ok = lambda v: v["sparks"] and not v["old"] and all(
    (s["pts"] >= 3 and s["marks"] == 1 or s["pts"] == 0 and s["marks"] <= 1) and s["band"] <= 60.01 and (s["round"] is None or .8 < s["round"] < 1.25)
    for s in v["sparks"])


# a lab's chart on its own under root (#302, chartkit.js ckSolo: a share link's histories, the visit summary's trends):
# each one's role and words, whether it's drawn (a viewBox), its width against its box's, its dots and ▲/▼/◆ (each with
# a <title>), its band's steps, its line, and any of its labels past its edges
SOLO302_JS = r"""root => [...document.querySelectorAll(root + ' svg.ck-solo')].map(s => {
  const b = s.getBoundingClientRect(), box = s.parentElement.getBoundingClientRect();
  return {drawn: s.hasAttribute('viewBox'), role: s.getAttribute('role'), label: s.getAttribute('aria-label') || '', shown: s.checkVisibility(),
    w: Math.round(b.width), box: Math.round(box.width), dots: s.querySelectorAll('circle.pt').length, abn: s.querySelectorAll('path.pt.abn').length,
    titled: s.querySelectorAll(':is(circle.pt, path.pt.abn) > title').length, band: s.querySelectorAll('.refband').length, line: s.querySelectorAll('path.line').length,
    out: [...s.querySelectorAll('text')].filter(t => { const r = t.getBoundingClientRect();
      return r.width && (r.left < b.left - 0.5 || r.right > b.right + 0.5 || r.top < b.top - 0.5 || r.bottom > b.bottom + 0.5); }).map(t => t.textContent)};
})"""
# … and whether each is drawn whole: a picture named in words, as wide as its box, every mark titled, nothing past it
solo302_ok = lambda v: v and all(c["drawn"] and c["role"] == "img" and c["label"] and abs(c["w"] - c["box"]) <= 1 and c["line"] == 1
                                 and c["titled"] == c["dots"] + c["abn"] > 0 and not c["out"] for c in v)


# a tile's change line (Costs' figures' notes too, #260), as laid out (#330): each one that wraps, as its lines, when it ends in a short
# fragment (its last line under 40% of its longest, such as "▼ −0.03 since Aug 18," over "2026"), breaks a date, or has
# only the change on its first line ("▼ −0.03" over "since Aug 18, 2026", #374), or a line that starts with its "·"
# ("diagnosis" over "· Nov 12, 2026", #379); and each row of tiles whose sparklines don't start at the same height
# ([the tiles' container, the tops])
TILE_LINES_JS = r"""() => {
  const lines = e => {   // {text, left, right} per line the element's words are laid out on
    const out = [], walk = document.createTreeWalker(e, NodeFilter.SHOW_TEXT);
    for (let n; (n = walk.nextNode());) for (const m of n.data.matchAll(/\S+/g)) {
      const r = document.createRange(); r.setStart(n, m.index); r.setEnd(n, m.index + m[0].length);
      const rs = [...r.getClientRects()], last = out.at(-1); if (!rs.length) continue;
      if (last && Math.abs(last.top - rs[0].top) < 4) { last.text += " " + m[0]; last.r = rs.at(-1).right; }
      else out.push({top: rs[0].top, text: m[0], l: rs[0].left, r: rs.at(-1).right});
    }
    return out;
  };
  const date = /(\p{L}{2,}\.? \d{1,2},|\d{1,2}\.? \p{L}{2,}\.?|(?<!\p{L})\p{L}{2,}\.?)$/u, year = /^(\d{1,2},? )?\d{4}(?![-\d])/u;   // a month's short name, a year not a year-month-day date (#339, #345)
  const out = {n: 0, bad: [], uneven: []};
  for (const e of document.querySelectorAll('.tile .delta')) {
    if (!e.checkVisibility() || !e.textContent.trim()) continue;
    out.n++;
    const ls = lines(e), w = ls.map(l => l.r - l.l);
    if (ls.length > 1 && (w.at(-1) < .4 * Math.max(...w) || ls.some((l, i) => i && (year.test(l.text) && date.test(ls[i - 1].text) || l.text.startsWith("·")))
                          || / since /.test(e.textContent.replace(/\s+/g, " ")) && !/ since /.test(ls[0].text + " ")))
      out.bad.push(ls.map(l => l.text));
  }
  for (const g of document.querySelectorAll('.tiles')) {
    if (!g.checkVisibility()) continue;
    const rows = {};
    for (const t of g.children) {
      const s = t.querySelector('svg:not(.icon)'); if (!s) continue;   // its sparkline, not an icon (#257)
      (rows[Math.round(t.getBoundingClientRect().top)] ||= []).push(Math.round(s.getBoundingClientRect().top));
    }
    for (const v of Object.values(rows)) if (Math.max(...v) - Math.min(...v) > 1) out.uneven.push([g.parentElement.id || g.parentElement.className, v]);
  }
  return out;
}"""


# the tiles as laid out (#351): each one's label or value whose words run past its tile's edge (the text, not its box,
# which a grid or flex item keeps inside); each pair of tiles in one row or grid that overlap; and each row of tiles
# (a container's tiles with the same top) whose values don't end at the same height, so don't share one baseline
# a phone's tab bar's height (#268), as laid out: --tabbar holds a calc() with env(), which reading the property gives as text
TABBAR_JS = "(() => { const d = document.createElement('div'); d.style.height = 'var(--tabbar, 0px)'; document.body.append(d); const h = d.getBoundingClientRect().height; d.remove(); return h; })()"

TILE_FIT_JS = r"""() => {
  const out = {n: 0, rows: 0, wide: [], overlap: [], baseline: []};
  // the words as drawn: text in a visually hidden span (.vh, said to screen readers, #358) is clipped to nothing
  const ext = e => { const rs = [], w = document.createTreeWalker(e, NodeFilter.SHOW_TEXT);
    for (let n; (n = w.nextNode());) if (!n.parentElement.closest('.vh')) { const r = document.createRange(); r.selectNodeContents(n); rs.push(...[...r.getClientRects()].filter(x => x.width > 0)); }
    return rs.length ? {l: Math.min(...rs.map(x => x.left)), r: Math.max(...rs.map(x => x.right))} : null; };
  const name = t => (t.querySelector('.lbl')?.textContent || '').trim().slice(0, 30);
  const groups = new Map();
  for (const t of document.querySelectorAll('.tile')) {
    if (!t.checkVisibility()) continue;
    const box = t.parentElement.classList.contains('tile-tq') ? t.parentElement : t, b = box.getBoundingClientRect();
    if (!b.width) continue;
    out.n++;
    for (const p of t.querySelectorAll(':scope > .lbl, :scope > .val')) {
      const x = ext(p); if (!x) continue;
      if (x.r > b.right + .5 || x.l < b.left - .5) out.wide.push(`${name(t)}: its ${p.className} “${p.textContent.trim().slice(0, 24)}” ${Math.round(x.l)}–${Math.round(x.r)} in a tile ${Math.round(b.left)}–${Math.round(b.right)}`);
    }
    const g = box.parentElement; if (!groups.has(g)) groups.set(g, []);
    groups.get(g).push([t, b]);
  }
  for (const [g, ts] of groups) {
    for (let i = 0; i < ts.length; i++) for (let j = i + 1; j < ts.length; j++) {
      const a = ts[i][1], c = ts[j][1];
      if (Math.min(a.right, c.right) - Math.max(a.left, c.left) > .5 && Math.min(a.bottom, c.bottom) - Math.max(a.top, c.top) > .5)
        out.overlap.push(`${name(ts[i][0])} and ${name(ts[j][0])}`);
    }
    const rows = {};
    for (const [t, b] of ts) { const v = t.querySelector(':scope > .val'); if (v) (rows[Math.round(b.top)] ||= []).push([name(t), Math.round(v.getBoundingClientRect().bottom * 10) / 10]); }
    for (const r of Object.values(rows)) {
      if (r.length < 2) continue;
      out.rows++;
      const bs = r.map(x => x[1]);
      if (Math.max(...bs) - Math.min(...bs) > 1) out.baseline.push(`${g.id || g.className}: ${r.map(x => x.join(' ')).join(', ')}`);
    }
  }
  return out;
}"""

# every word of every tile shown in a page's grids (#722; the figures' .stats too, #753): its label, value, unit, change
# line and dates, each line of text as drawn (not its box, which a grid or flex item keeps inside) within its tile's
# edges, the "?" beside a key lab's with it; and each tile within its grid's edges, but in a row that scrolls sideways
# (#753: a grid's columns no wider than it). {n: tiles, past: each text or tile past its box, and by how much}
TILE_TEXT722_JS = r"""() => { const out = {n: 0, past: []};
  for (const t of document.querySelectorAll('main :is(.tiles, .stats) > :is(.tile, .tile-tq)')) {
    if (!t.checkVisibility()) continue;
    out.n++;
    const T = t.getBoundingClientRect(), name = (t.querySelector('.lbl')?.textContent || '').trim().slice(0, 30), w = document.createTreeWalker(t, NodeFilter.SHOW_TEXT);
    const G = t.parentElement.getBoundingClientRect(), g = Math.max(G.left - T.left, T.right - G.right);
    if (g > 1 && !/auto|scroll/.test(getComputedStyle(t.parentElement).overflowX)) out.past.push(`${name}: its tile ${Math.round(g)} px past its grid`);
    for (let n; (n = w.nextNode());) {
      if (!n.data.trim() || n.parentElement.closest('.vh')) continue;   // (said to screen readers, clipped)
      const r = document.createRange(); r.selectNodeContents(n);
      const d = Math.max(0, ...[...r.getClientRects()].filter(x => x.width).map(x => Math.max(T.left - x.left, x.right - T.right, T.top - x.top, x.bottom - T.bottom)));
      if (d > 1) out.past.push(`${name}: “${n.data.trim().slice(0, 24)}” ${Math.round(d)} px past its tile`);
    }
  }
  return out; }"""
# #722's check for words that aren't tiles' (#849): each line of text drawn in each element shown that matches sel (an
# SVG's text by its box), scrolled into view, within the edges of its closest box (#819's longer words: a Timeline's
# badge in its row, the heatmap's counts and their heading in #hmWrap, which clips) and of the screen.
# {n: elements, past: each text past its box, and by how much, said: the words of those saying "flagged"}
TEXT_IN849_JS = r"""([sel, box]) => { const out = {n: 0, past: [], said: []}, V = document.documentElement.clientWidth;
  for (const e of document.querySelectorAll(sel)) {
    if (!e.checkVisibility()) continue;
    e.scrollIntoView({block: 'center'});
    out.n++;
    const B = e.closest(box).getBoundingClientRect(), w = document.createTreeWalker(e, NodeFilter.SHOW_TEXT);
    const said = [...e.childNodes].filter(c => c.nodeName !== 'title').map(c => c.textContent).join('').trim();
    if (/flagged/i.test(said)) out.said.push(said);
    for (let t; (t = w.nextNode());) {
      if (!t.data.trim() || t.parentElement.closest('.vh, title')) continue;
      const r = document.createRange(); r.selectNodeContents(t);
      const rs = t.parentElement.closest('svg') ? [t.parentElement.getBoundingClientRect()] : [...r.getClientRects()].filter(x => x.width);
      const d = Math.max(0, ...rs.map(x => Math.max(B.left - x.left, x.right - B.right, -x.left, x.right - V)));
      if (d > 1) out.past.push(`“${t.data.trim().slice(0, 30)}” ${Math.round(d)} px past its box or the screen`);
    }
  }
  out.said = [...new Set(out.said)];
  return out; }"""
# the sizes every grid of tiles is checked at with text at 200% (#753): phones, the widths between a phone and a laptop
# where a column's floor in px left a value no room, a laptop's, and a phone held sideways; and that text, #622's
# (the --fs-* tokens and the root's size doubled), as a stylesheet the page adopts ("" for none)
TILE_SIZES753 = [(320, 800), (360, 800), (375, 800), (412, 800), (700, 800), (768, 800), (900, 800), (1100, 900), (1400, 900), (844, 390)]
BIG_TEXT_CSS = ":root{--fs-1:23px;--fs-2:25px;--fs-3:28px;--fs-4:31px;--fs-5:36px;--fs-6:44px;--fs-7:56px} html{font-size:200%}"
ADOPT_CSS_JS = "css => { const s = new CSSStyleSheet(); s.replaceSync(css); document.adoptedStyleSheets = css ? [s] : []; }"
# every pick-one (.seg) shown under root (#1074, #800, #806): {n: its options, bad: one scrolling, past the screen or
# an option cut or past it, lines: each one's rows of options, but those that wrapped already (.wrap)}
SEG1074_JS = r"""root => { const r = e => e.getBoundingClientRect(), out = {n: 0, bad: [], lines: []};
  for (const s of document.querySelectorAll(root + ' .seg')) { if (!s.checkVisibility()) continue; const S = r(s), tops = new Set(), name = s.getAttribute('aria-label') || s.className;
    if (s.scrollWidth > s.clientWidth + 1) out.bad.push(`${name} scrolls ${s.scrollWidth} in ${s.clientWidth}`);
    if (S.left < -.5 || S.right > document.documentElement.clientWidth + .5) out.bad.push(`${name} past the screen`);
    for (const b of s.children) { if (!b.checkVisibility()) continue; const B = r(b); out.n++; tops.add(Math.round(B.top));
      if (B.left < S.left - 1 || B.right > S.right + 1 || b.scrollWidth > b.clientWidth + 1) out.bad.push(`“${b.textContent.trim()}” cut`); }
    if (!s.matches('.wrap')) out.lines.push(tops.size); }
  return out; }"""
# Labs' Latest (#993) beside the charts' tables, for the period shown: {latest: each row's [lab, unit, its values each
# [as shown, its flag's word], its line under them (ranges · reported · day …), its change (#995) or null], charts:
# each lab's chart's [lab, unit, its table's rows, newest first, each its cells' words]}; Labs' view, its labs and
# tables as they were after
LATEST993_JS = r"""async () => {
  const frame = () => new Promise(r => requestAnimationFrame(() => setTimeout(r))), was = [state.labsView, new Set(state.sel), new Set(state.tables), state.tab];
  switchTab('labs', 'latest'); await frame();
  const latest = [...document.querySelectorAll('#ltRows .lt-row')].map(a => [a.dataset.lab, a.dataset.unit,
    [...a.querySelectorAll('.lt-v')].map(v => [[...v.childNodes].filter(n => !n.matches?.('.st, .vh')).map(n => n.textContent).join('').trim(),
      (v.querySelector('.st')?.textContent || '').replace(/[▲▼◆]/g, '').trim()]),
    a.querySelector('.s').textContent, (c => c && [...c.childNodes].filter(n => !n.matches?.('.vh')).map(n => n.textContent).join(''))(a.querySelector('.c'))]);
  state.sel = new Set(SERIES.filter(s => !s.watch).map(s => s.name)); state.tables = new Set(state.sel); switchTab('labs', 'chart'); await frame();
  const charts = [...document.querySelectorAll('#charts .chart')].map(c => [c.dataset.lab, c._s ? c._s.unit : c.querySelector('.hd-sub .unit')?.textContent.split(' ')[0],
    [...c.querySelectorAll('table.data tbody tr')].map(r => [...r.cells].map(x => x.textContent))]);
  [state.labsView, state.sel, state.tables] = was; switchTab(was[3]);
  return {latest, charts}; }"""


def change993(said, cur, prev):
    """What's wrong with Latest's change (#995) to a result its chart's table gives as cur (its value cell) from the result
    before (prev's, None for none): "–" with none; "change not worked out" from or to a value given as a bound; else the
    difference of the two as printed, to the places either is printed with, "↑ 0.4", "↓ 12" or "no change" (a converted
    value's number has more places than it's printed with, and the change is of the numbers: within what printing each
    and the change rounds off), else None"""
    if prev is None:
        return None if said == "–" else f"“{said}” with no result before it"
    conv, cur, prev = " (reported " in cur + prev, cur.split(" (reported ")[0], prev.split(" (reported ")[0]
    if any(re.match(r"[<>≤≥=]", x) for x in (cur, prev)):
        return None if said == "change not worked out" else f"“{said}” from {prev} to {cur}"
    a, b = (re.match(r"-?\d+(?:\.\d+)?", x.replace(",", ".")) for x in (cur, prev))
    if not a or not b:
        return f"“{said}”: {prev} to {cur} not read"
    places = [len(x[0].partition(".")[2]) for x in (a, b)]
    dec = max(places)
    d, tol = Decimal(a[0]) - Decimal(b[0]), sum(Decimal(5).scaleb(-k - 1) for k in places + [dec]) if conv else 0
    m = re.fullmatch(r"([↑↓]) (\d+(?:\.(\d+))?)", said)
    got = Decimal(0) if said == "no change" else m and Decimal(m[2]) * (1 if m[1] == "↑" else -1)
    if got is None or not got and said != "no change" or m and len(m[3] or "") != dec or abs(got - d) > tol:
        return f"“{said}” from {prev} to {cur} (by {d})"
    return None


def latest993(got):
    """What's wrong with Labs' Latest (LATEST993_JS's) against each lab's chart (#993): every lab with a result in the
    period listed once, with none none; each the results at its chart's latest time (the top of its table, two at one
    time both, in any order), each its value and unit, flag and range as the table gives them, and its day; and each
    one's change from the result before that time, the next row of the table (#995, change993: those say "change of")"""
    bad, rows = [] if got["charts"] else ["no chart to hold it against"], {(n, u): r for n, u, *r in got["latest"]}
    if len(rows) != len(got["latest"]):
        bad.append(f"a lab listed twice: {[r[:2] for r in got['latest']]}")
    for n, u, trs in got["charts"]:
        r = rows.pop((n, u), None)
        if not trs or not r:
            if r or trs:
                bad.append(f"{n} ({u}): {'listed' if r else 'not listed'}, with {len(trs)} results in the period")
            continue
        at = [t for t in trs if t[0] == trs[0][0]]   # its latest time's
        ranges, said = r[1].split(" · ")[0].split("; "), r[2].split("; ") if r[2] not in (None, "–") else [r[2]] * len(r[0])
        if len(ranges) == 1:   # (one said once for two at one time that have it, #1027)
            ranges = [ranges[0].replace("no range on their reports", "no range on its report")] * len(r[0])
        got_t = sorted([v, f, g, c] for (v, f), g, c in zip(r[0], ranges, said))
        want_t = sorted([t[1].split(" (reported ")[0], re.sub(r"[▲▼◆]\s*", "", t[3]).strip(), "ref " + t[2].split(" · ")[0] if t[2].split(" · ")[0] else "no range on its report", t[1]] for t in at)
        if len(ranges) != len(r[0]) or len(said) != len(r[0]) or [x[:3] for x in got_t] != [x[:3] for x in want_t] or not any(trs[0][0].startswith(p) for p in r[1].split(" · ")[1:]):
            bad.append(f"{n} ({u}): {r[0]} {r[1]!r}, its chart's latest {[x[:3] for x in want_t]} on {trs[0][0]}")
        elif r[2] is not None:
            bad += [f"change of {n} ({u}): {w}" for x, y in zip(got_t, want_t) if (w := change993(x[3], y[3], trs[len(at)][1] if len(trs) > len(at) else None))]
    return bad + [f"{n} ({u}) listed with no chart" for n, u in rows]


def tiles_big753(page, settle, show):
    """Every tile grid shown, at each of #753's sizes with text at 200%: the words or tiles past their box
    (TILE_TEXT722_JS) and the tiles over another (TILE_FIT_JS), as [where and size: what], and {where and size: tiles
    measured}. show(width) puts up each thing to measure at that width in turn, yielding its name; the page is left at
    1400 px, its text as usual"""
    bad, n = [], {}
    page.evaluate(ADOPT_CSS_JS, BIG_TEXT_CSS)
    for width, height in TILE_SIZES753:
        page.set_viewport_size({"width": width, "height": height})
        for where in show(width):
            settle(300)
            got, fit = page.evaluate(TILE_TEXT722_JS), page.evaluate(TILE_FIT_JS)
            n[f"{where} {width}×{height}"] = got["n"]
            bad += [f"{where} {width}×{height}: {x}" for x in got["past"] + fit["overlap"]]
    page.evaluate(ADOPT_CSS_JS, "")
    page.set_viewport_size({"width": 1400, "height": 900})
    return bad, n

# a button beside a field (#352): each button shown on one line with a field of its row (the button's parent holds the
# field, or the label around it, and their middles are within a few px), as {pairs found, those whose heights differ}
FIELD_ROWS_JS = r"""() => { const out = {n: 0, bad: []};
  const field = 'input:not([type=checkbox],[type=radio],[type=range],[type=file],[type=hidden],[type=color]), select';
  for (const b of document.querySelectorAll('main .btn')) {
    if (!b.checkVisibility()) continue;
    const rb = b.getBoundingClientRect();
    for (const f of b.parentElement.querySelectorAll(field)) {
      if (!f.checkVisibility()) continue;
      const rf = f.getBoundingClientRect(), mid = r => (r.top + r.bottom) / 2;
      if (Math.abs(mid(rb) - mid(rf)) > 4 || rf.right > rb.left + 1 && rb.right > rf.left + 1) continue;   // not on its line, or not beside it
      out.n++;
      if (Math.abs(rb.height - rf.height) > .5) out.bad.push(`“${b.textContent.trim()}” ${Math.round(rb.height)} px beside ${f.tagName.toLowerCase()} “${f.getAttribute('aria-label') || f.placeholder || f.name || f.value.slice(0, 20)}” ${Math.round(rf.height)} px`);
    }
  }
  return out; }"""

# the controls of #353, on the page shown: each checkbox shown in <main> that isn't a switch, a toggle chip's or in a
# table (a bare on/off box), each file input that the browser draws (not see-through inside a .btn.pick), and the
# sizes of the quiet icon buttons: a chart's ✕, the ✎ and Settings' drag grip
CONTROLS353_JS = r"""() => {
  const targetOf = e => { const r = e.getBoundingClientRect(), a = getComputedStyle(e, '::after');   // a see-through ::after out past its edges is its target too (the ✎, #373)
    const o = a.content !== 'none' && a.position === 'absolute' ? Math.max(0, -parseFloat(a.top) || 0) : 0; return [r.width + 2 * o, r.height + 2 * o]; };
  const bare = [...document.querySelectorAll('main input[type=checkbox]')].filter(i => i.checkVisibility())
    .filter(i => !i.closest('label.switch, .toggle, table') && i.getAttribute('role') !== 'switch').map(i => (i.closest('label') || i.parentElement).textContent.trim().slice(0, 40));
  const files = [...document.querySelectorAll('input[type=file]')].filter(i => i.closest('main, dialog') && i.parentElement.checkVisibility())
    .map(i => [i.id || i.className, !!i.closest('.btn.pick') && getComputedStyle(i).opacity === '0']);
  const quiet = [...document.querySelectorAll('.chart .hd>.btn, .rename-btn, .set-grip')].filter(b => b.checkVisibility())
    .map(b => { const [w, h] = targetOf(b); return [b.className, Math.round(w), Math.round(h)]; });
  const toggles = [...document.querySelectorAll('main label.toggle')].filter(l => l.checkVisibility()).map(l => l.textContent.trim());
  return {bare, files, quiet, toggles}; }"""

# the swap to the fonts (#329): the cards and tiles a page draws, by name, with their heights; and the Timeline's kinds'
# chips, by kind, with where they end on the page (#434: their words' room doesn't depend on the font, so none moves)
SWAP_BOXES_JS = """() => Object.fromEntries([...[...document.querySelectorAll('main .card, main .tile, .sets .set')]
  .filter(e => e.checkVisibility()).map((e, i) => [`${e.className.split(' ')[0]} ${i} ${(e.querySelector('h1,h2,h3,.lbl,.l')?.textContent || '').trim().slice(0, 40)}`,
    Math.round(e.getBoundingClientRect().height * 10) / 10]),
  ...[...document.querySelectorAll('#chips .kind')].filter(e => e.checkVisibility()).map(e => { const b = e.getBoundingClientRect();
    return [`kind ${e.firstElementChild.dataset.k}`, Math.round(b.right * 10) / 10]; })])"""
# the button's sizes (#258): each button shown (.btn, the top bar's and the drawer's, the tabs, the period's More…), and
# each segmented control, toggle chip and action chip (#259), whose height isn't one of the sizes, 24, 32 or 40 px, or
# 44 px on a phone; one whose words wrap onto more lines may be taller
CONTROL_SIZES_JS = r"""phone => { const ok = phone ? [44] : [24, 32, 40], out = [];
  const targetOf = e => { const r = e.getBoundingClientRect(), a = getComputedStyle(e, '::after');   // a see-through ::after out past its edges is its target too (the ✎, #373)
    const o = a.content !== 'none' && a.position === 'absolute' ? Math.max(0, -parseFloat(a.top) || 0) : 0; return [r.width + 2 * o, r.height + 2 * o]; };
  for (const e of document.querySelectorAll('.btn, .iconbtn, .tabs > a, .tab-more, .period-more-btn, .seg, .toggle, .chip')) {
    const h = Math.round(targetOf(e)[1] * 10) / 10;
    if (!h || !e.checkVisibility() || ok.some(v => Math.abs(h - v) < .5)) continue;
    const r = document.createRange(); r.selectNodeContents(e);
    if (h > Math.max(...ok) && new Set([...r.getClientRects()].filter(x => x.width > 1).map(x => Math.round(x.top))).size > 1) continue;
    out.push(`${e.tagName.toLowerCase()}.${[...e.classList].join('.')} “${(e.getAttribute('aria-label') || e.textContent).trim().slice(0, 24)}” ${h}`);
  }
  return out; }"""
# #371 (#358's rule): a title on something that takes focus, whose words are on no screen: a title shows for neither the
# keyboard nor touch, and screen readers don't reliably read it. Each control shown that the keyboard reaches (an
# iframe's title is its name, so not those), with a title any of whose words (but the little ones: "to", "of") is in
# neither its text as drawn nor its name (aria-labelledby, aria-label, its label, its text, an image's alt in it), each
# as “its title” on what it's on. A hint beside a name that says it all stays a title (a row's grip: “Drag to reorder”)
TITLES_JS = r"""() => { const out = [], words = s => ((s || '').toLowerCase().match(/[\p{L}\p{N}]+/gu) || []).filter(w => w.length > 2 || /\d/.test(w));
  const of = ids => (ids || '').split(' ').map(x => document.getElementById(x)?.textContent || '').join(' ');
  for (const e of document.querySelectorAll('[title]:is(a[href], button, input, select, textarea, summary, [tabindex])')) {
    if (e.tabIndex < 0 || e.disabled || e.closest('[inert]') || !e.checkVisibility()) continue;
    const name = [of(e.getAttribute('aria-labelledby')), e.getAttribute('aria-label'), [...(e.labels || [])].map(l => l.textContent).join(' '),
      e.textContent, [...e.querySelectorAll('img[alt]')].map(i => i.alt).join(' '), e.value, e.placeholder, e.innerText].join(' ');
    const have = new Set(words(name));
    if (!words(e.title).every(w => have.has(w))) out.push(`“${e.title.slice(0, 60)}” on ${e.tagName.toLowerCase()} “${(e.getAttribute('aria-label') || e.textContent).trim().slice(0, 30)}”`);
  }
  return out; }"""
SWAP_FONTS_JS = "() => [...document.fonts].filter(f => f.status === 'loaded').map(f => f.family).filter((f, i, a) => a.indexOf(f) === i).sort()"
# the fonts the page has fetched (#253, #328), read once the Overview's tiles are drawn (their values are its first text in
# Source Serif) and Source Serif has been fetched, or 10 s after: on a slow runner the records load well before the
# tiles ask for it (#380). Polled from here, as the CSP refuses wait_for_function's string
FONTS_FETCHED_JS = r"""async () => {
  const wait = async (ok, ms) => { for (const end = Date.now() + ms; !ok() && Date.now() < end;) await new Promise(r => setTimeout(r, 50)); };
  const fonts = () => performance.getEntriesByType('resource').map(e => new URL(e.name).pathname).filter(p => p.startsWith('/fonts/'));
  await wait(() => document.querySelector('#view-overview .tile .val')?.checkVisibility(), 10000);
  await document.fonts.ready;
  await wait(() => fonts().some(p => p.startsWith('/fonts/source-serif-')), 10000);
  return fonts().sort();
}"""


def font_swap(browser, state, url, width):
    """A page loaded with www/fonts/ held back, so it's drawn in base.css's fallbacks, then the fonts let through (#329).
    Returns {box: (height in the fallback, height in the font)} for each card or tile whose height changed, how many
    boxes there were, the layout shift after the fonts were let through, and the font families loaded before and
    after. No service worker, so the fonts come from the network."""
    ctx = browser.new_context(storage_state=state, service_workers="block", viewport={"width": width, "height": 900})
    held = []
    ctx.route("**/fonts/**", lambda route: held.append(route))   # answered once the page is drawn
    pg = ctx.new_page()
    pg.goto(url, wait_until="domcontentloaded")   # not "load": that waits for the fonts
    for _ in range(100):
        if pg.evaluate("performance.getEntriesByName('sanguity:ready').length > 0 || !!document.querySelector('.sets .set')"):
            break
        pg.wait_for_timeout(100)
    pg.wait_for_timeout(1000)
    before, fonts_before = pg.evaluate(SWAP_BOXES_JS), pg.evaluate(SWAP_FONTS_JS)
    pg.evaluate("""() => { window.__swapShift = 0; new PerformanceObserver(l => { for (const e of l.getEntries()) if (!e.hadRecentInput) window.__swapShift += e.value; })
      .observe({type: 'layout-shift'}); }""")
    # Source Serif first and drawn alone for a moment, then Inter: either may arrive first, and a row that fits in
    # both fonts and in neither may not fit in the serif beside Inter's fallback (#426: a heading pushed its Chart |
    # Table under it for that frame). Without the order the check caught that only now and then
    for r in sorted(held, key=lambda r: "/fonts/source-serif-" not in r.request.url):
        r.continue_()
        if "/fonts/source-serif-" in r.request.url:
            pg.evaluate("""async () => { for (let i = 0; i < 100 && ![...document.fonts].some(f => f.family === 'Source Serif 4' && f.status === 'loaded'); i++)
              await new Promise(r => setTimeout(r, 20)); await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r))); }""")
    ctx.unroute("**/fonts/**")
    pg.evaluate("document.fonts.ready.then(() => new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r))))")
    pg.wait_for_timeout(500)
    after, fonts_after, shift = pg.evaluate(SWAP_BOXES_JS), pg.evaluate(SWAP_FONTS_JS), pg.evaluate("window.__swapShift")
    ctx.close()
    changed = {k: (h, after[k]) for k, h in before.items() if k in after and abs(after[k] - h) > 0.5}
    return changed, len(before), round(shift, 4), fonts_before, fonts_after


