            sh754 = js("t => fetch('api/share/view', {method: 'POST', headers: {'X-Sanguity': '1', 'Content-Type': 'application/json'}, body: JSON.stringify({token: t})}).then(r => r.json())",
                       lk754[1]["path"].split("#", 1)[1]) if lk754[0] == 200 else {}
