            # #309: and taking .row's padding off left the rows of buttons with no space under them ("Back up now" sat on
            # Admin → Backups' Schedule heading): each row is 8 px or more from what follows it, in its card, at 1400 and 320 px
            rows_gap = r"""(() => {
              const vis = e => e.checkVisibility() && e.getBoundingClientRect().height > 0, out = [];
              const name = e => e.tagName.toLowerCase() + (e.id ? '#' + e.id : '') + ` "${(e.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 24)}"`;
              for (const r of document.querySelectorAll('main .row')) {
                if (!vis(r)) continue;
                const bottom = r.getBoundingClientRect().bottom;
                let n = r, next = null;
                while (!next && n.parentElement && !n.matches('section, .card, main, details, li, td')) {
                  for (let s = n.nextElementSibling; s && !next; s = s.nextElementSibling) if (vis(s) && s.getBoundingClientRect().top >= bottom - 2) next = s;
                  n = n.parentElement;
                }
                const gap = next && next.getBoundingClientRect().top - bottom;
                if (next && gap < 7.5) out.push(`row ${name(r)}: ${gap.toFixed(1)} px above ${name(next)}`);
              }
              return out;
            })()"""
            bad, seen, gaps = [], [], []
            for width in (1400, 320):
                page.set_viewport_size({"width": width, "height": 900})
                for path in (f"sources.html?profile={conn_pid}", "sharing.html?profile=1", "settings.html?profile=1"):   # (its You and Install: Account and Admin before #991)
                    page.goto(base + "/" + path)
                    page.wait_for_selector(".set-nav a[data-group]", state="attached", timeout=10000)
                    settle(300)
                    for g in js("[...document.querySelectorAll('.set-nav a[data-group]')].map(a => a.dataset.group)"):
                        open_group(page, g)
                        settle(150)
                        if width == 1400:
                            bad += [f"{path.split('.')[0]} #{g}: {x}" for x in js(rows_typed)]
                            seen.append(g)
                        gaps += [f"{path.split('.')[0]} #{g} at {width} px: {x}" for x in js(rows_gap)]
            page.set_viewport_size({"width": 1400, "height": 900})
            check("every group of Sources, Sharing and Settings (its You and Install too, #991): rows of buttons have no divider or pointer, "
                  "and typed values are weight 400 (#246)", len(seen) >= 25 and not bad, bad[:8] or f"{len(seen)} groups")
            check("…and each row of buttons is at least 8 px above what follows it, at 1400 and 320 px (#309)", not gaps, gaps[:8])

            # ---- every page at 375 px (#61): each records tab (Labs as charts and as a heatmap) with its filters open, an
            # event's drawer and the top bar's menus; every group of Sources (the profile with connected sources and
            # imports), Sharing, Settings, Account and Admin; and the sign-in page with no session; in light and dark:
            # nothing scrolls sideways, and no control is cut off at the edge or overlaps another (phone_fits). The
            # shared page (share.html) is checked the same way with the share links, under the real CSP.
            phone_known = ()   # problems owned by another issue, each with the issue's number beside it: none now
            theme_was = js("localStorage.getItem('ht-theme')")
            page.set_viewport_size({"width": 375, "height": 800})
            for theme in ("light", "dark"):
                js(f"localStorage.setItem('ht-theme', '{theme}')")
                page.goto(base + "/")
                page.wait_for_function("typeof EV !== 'undefined' && EV.length > 0 && typeof booted !== 'undefined' && booted", timeout=20000)
                bad = []
                for t in ("overview", "health", "medications", "timeline", "heatmap", "labs", "costs"):
                    open_tab(t)
                    settle(250)
                    bad += phone_fits(page, t, phone_known)
                    for sheet in ("#ftoggle", "#periodPill"):   # the Filters and period sheets (#269)
                        if page.is_visible(sheet):
                            page.click(sheet)
                            settle(300)
                            bad += phone_fits(page, f"{t} with {sheet} open", phone_known)
                            page.keyboard.press("Escape")
                            settle(300)
                    if t == "timeline":
                        page.click("#list .tl-row >> nth=0")
                        page.wait_for_function("document.getElementById('drawer').classList.contains('open')", timeout=5000)
                        settle(250)
                        bad += phone_fits(page, "the drawer", phone_known)
                        page.keyboard.press("Escape")
                        settle(250)
                for m in ("#profileMenuBtn", "#addMenuBtn", "#userMenuBtn"):
                    page.click(m)
                    settle(300)
                    bad += phone_fits(page, m + " open", phone_known)
                    page.keyboard.press("Escape")
                    settle(300)
                check(f"at 375 px, {theme}: every records tab, with its filters open, the drawer and the menus fit, no control cut off or overlapping (#61)",
                      js("document.documentElement.dataset.theme") == theme and not bad, bad[:8] or "")
                bad, seen = [], []
                for path in (f"sources.html?profile={conn_pid}", "sharing.html?profile=1", "settings.html?profile=1"):   # (its You and Install: Account and Admin before #991)
                    page.goto(base + "/" + path)
                    page.wait_for_selector(".set-nav a[data-group]", state="attached", timeout=10000)
                    settle(300)
                    for g in js("[...document.querySelectorAll('.set-nav a[data-group]')].map(a => a.dataset.group)"):
                        open_group(page, g)
                        settle(150)
                        bad += phone_fits(page, f"{path.split('.')[0]} #{g}", phone_known)
                        seen.append(f"{path.split('.')[0]}#{g}")
                ctx = browser.new_context(viewport={"width": 375, "height": 800}, color_scheme=theme)   # no session: the sign-in page
                lp = ctx.new_page()
                lp.goto(base + "/login.html")
                lp.wait_for_selector("#u", timeout=10000)
                bad += phone_fits(lp, "sign-in", phone_known)
                ctx.close()
                check(f"at 375 px, {theme}: every group of Sources, Sharing, Settings, Account and Admin, and the sign-in page, fit, "
                      "no control cut off or overlapping (#61)", len(seen) >= 25 and not bad, bad[:8] or f"{len(seen)} groups")
            js(f"localStorage.setItem('ht-theme', {json.dumps(theme_was)})" if theme_was else "localStorage.removeItem('ht-theme')")
            page.set_viewport_size({"width": 1400, "height": 900})

            # ---- #354: an icon beside the words of every sidebar link, kind chip, Timeline row, Add item and item of your
            # menu: exactly one svg.icon first in it, hidden from assistive technology (so its name is its words), its <use>
            # naming a symbol the sprite has and drawn (not 0 by 0) where it's shown. A chip's icon is its kind's (KIND_ICON).
            ICON_EACH = r"""async ([sels, open]) => {
              const sprite = await (await fetch(ICON_SPRITE)).text(), ids = new Set([...sprite.matchAll(/<symbol id="([^"]+)"/g)].map(m => m[1]));
              const out = {n: {}, bad: []};
              for (const sel of sels) {
                out.n[sel] = 0;
                for (const x of document.querySelectorAll(sel)) {
                  if (x.hidden) continue;
                  out.n[sel]++;
                  const icons = x.querySelectorAll('svg.icon'), s = icons[0], u = s && s.querySelector('use'), id = u && (u.getAttribute('href') || '').split('#')[1];
                  const say = `${sel} “${x.textContent.trim().slice(0, 30)}”`;
                  if (icons.length !== 1) { out.bad.push(`${say}: ${icons.length} icons`); continue; }
                  if (s.getAttribute('aria-hidden') !== 'true' || s.textContent.trim()) out.bad.push(`${say}: its icon could be read`);
                  if (!ids.has(id)) out.bad.push(`${say}: #${id} isn't in the sprite`);
                  if ((open || x.checkVisibility()) && !(u.getBBox().width && s.getBoundingClientRect().width)) out.bad.push(`${say}: not drawn`);
                  if (x.matches('#chips .toggle') && !s.classList.contains('i-' + KIND_ICON[x.dataset.k])) out.bad.push(`${say}: not its kind's icon`);
                }
              }
              return out;
            }"""
            icons_bad, icons_n = [], {}
            def icons_in(sels, open=False):
                r = page.evaluate(ICON_EACH, [sels, open])
                icons_n.update(r["n"]); icons_bad.extend(r["bad"])
            page.goto(base + "/")
            page.wait_for_function("typeof EV !== 'undefined' && EV.length > 0 && typeof booted !== 'undefined' && booted", timeout=20000)
            open_tab("timeline")
            settle(300)
            icons_in(["#chips .toggle", "#list .tl-row"])
            for m in ("profileMenu", "addMenu", "userMenu"):
                page.click(f"#{m}Btn")
                page.wait_for_selector(f"#{m}List:popover-open", timeout=5000)
                icons_in([f"#{m}List [role=menuitem]"], open=True)
                page.keyboard.press("Escape")
            # Dark mode / Light mode: its words change, its icon stays (twice, so the theme is as it was)
            item = "(t => [t.textContent.trim(), t.querySelectorAll('svg.icon').length, !!t.firstElementChild?.matches('svg.icon')])(document.getElementById('theme'))"
            theme_item = [js(item)]
            for _ in range(2):
                if not js("!!document.querySelector('#userMenuList:popover-open')"):
                    page.click("#userMenuBtn")
                was_t = theme_item[-1][0]
                page.click("#theme")
                page.wait_for_selector("#userMenuList:not(:popover-open)", state="attached", timeout=5000)   # (closed once picked, a task later)
                try:   # (its words change once the theme is saved and drawn: on a busy runner, after the menu closes)
                    page.wait_for_function("t => document.getElementById('theme').textContent.trim() !== t", arg=was_t, timeout=5000)
                except Exception:
                    pass
                theme_item.append(js(item))
            if js("!!document.querySelector('#userMenuList:popover-open')"):
                page.keyboard.press("Escape")
            for path, nav in (("settings.html", "#setNav"), ("sources.html", "#srcNav"), ("sharing.html", "#shrNav")):   # (Account's and Admin's in Settings', #991)
                page.goto(base + "/" + path)
                page.wait_for_selector(f"{nav} a[data-group]", timeout=10000)
                settle(1200)   # (You's and Install's groups, once this person's are drawn)
                icons_in([f"{nav} a[data-group]"])
            want = {"#setNav a[data-group]": 16, "#srcNav a[data-group]": 7, "#shrNav a[data-group]": 6,   # (#1114: Install's Lab name matches gone)
                    "#profileMenuList [role=menuitem]": 3, "#addMenuList [role=menuitem]": 7, "#userMenuList [role=menuitem]": 4}
            check("icons (#354): one Lucide icon, hidden from screen readers and drawn from a symbol the sprite has, in each link of the "
                  "three sidebars, each kind chip (its kind's), each Timeline row and each item of the profile menu, the Add menu and your menu",
                  not icons_bad and all(icons_n.get(k, 0) >= v for k, v in want.items()) and icons_n["#chips .toggle"] >= 10 and icons_n["#list .tl-row"] > 50,
                  icons_bad[:10] or icons_n)
            check("…and the Dark mode item, turned Light mode and back, keeps its icon before its words",
                  sorted(x[0] for x in theme_item[:2]) == ["Dark mode", "Light mode"] and theme_item[2] == theme_item[0]
                  and all(x[1:] == [1, True] for x in theme_item), theme_item)
            js(f"localStorage.setItem('ht-theme', {json.dumps(theme_was)})" if theme_was else "localStorage.removeItem('ht-theme')")
            page.goto(base + "/")
            page.wait_for_function("typeof EV !== 'undefined' && EV.length > 0 && typeof booted !== 'undefined' && booted", timeout=20000)

            # ---- WCAG 2.2 AA (#202, docs/accessibility.md): axe-core's WCAG 2.0, 2.1 and 2.2 A and AA rules (axe_check) on
            # every page and its main states, in light and dark: each records tab (Labs as charts and as a heatmap, each also
            # as its table), an event's drawer for several kinds, the app's own dialog (ask(), with a box to type in), the
            # More… period menu, a kind's ⋯ menu and the top bar's two menus; every group of Sources, Sharing, Settings,
            # Account and Admin; the guide and the provider finder; the sign-in page with no session. A serious or critical
            # finding fails; moderate and minor ones are listed under a passing check. (The shared page, setup and a fresh
            # install's empty tabs are checked where they're opened: share links and first run.) Then the keyboard: Tab and
            # Shift+Tab through each records tab and page at 375 px, every stop showing focus and none under a sticky bar;
            # every page at 320 px (400% zoom) and with WCAG's text spacing fitting; and in forced colours, the filled
            # buttons keep an edge. On each of them too, no link is in the browser's own blue (#247: links are in the accent).
            t_axe, axe_bad, axe_other, axe_seen = time.time(), [], [], []
            ua_links, links_seen = [], [0]
            outlines, outline_bad = [], []   # #331: each page's heading outline (in light: it's the same in dark)
            marks_bad = []   # #1061: axe's landmark rules on each of those pages (in light), and the records tabs at 360 px too
            th_bad = []   # #1075: axe's empty-table-header on all of them, in light
            sizes_bad, sizes_seen = [], [0]   # #258: buttons whose height isn't one of the sizes
            titles_bad = []   # #371: titles on controls that say what's on no screen
            # Chromium's own link colour, light and dark (a visited link's purple reads as this to scripts too)
            UA_LINKS = """(() => { const as = [...document.querySelectorAll('a[href]')].filter(a => a.checkVisibility());
              return [as.length, as.filter(a => ['rgb(0, 0, 238)', 'rgb(158, 158, 255)'].includes(getComputedStyle(a).color)).map(a => a.textContent.trim().slice(0, 40))]; })()"""
            icon_bad, icons_seen = [], [0]   # #257: the icons on each of them
            def axe_at(pg, label, outline=False):
                bad_, other_ = axe_check(pg, label)
                axe_bad.extend(bad_); axe_other.extend(other_); axe_seen.append(label)
                n, ib = icon_audit(pg, label)
                icons_seen[0] += n; icon_bad.extend(ib)
                if outline and label.startswith("light "):
                    o, ob = heading_outline(pg, label[6:])
                    outlines.append(o); outline_bad.extend(ob)
                    marks_bad.extend(f"{label[6:]}: {v}" for v in pg.evaluate(AXE_LANDMARKS))
                n, blue = pg.evaluate(UA_LINKS)
                links_seen[0] += n
                if label.startswith("light "):
                    th_bad.extend(f"{label[6:]}: {t}" for t in pg.evaluate(AXE_EMPTY_TH))
                    sizes_seen[0] += 1
                    sizes_bad.extend(f"{label[6:]}: {b}" for b in pg.evaluate(CONTROL_SIZES_JS, pg.viewport_size["width"] <= 640))
                    titles_bad.extend(f"{label[6:]}: {t}" for t in pg.evaluate(TITLES_JS))
                ua_links.extend(f"{label}: “{t}”" for t in blue)
            theme_was = js("localStorage.getItem('ht-theme')")
            for theme in ("light", "dark"):
                js(f"localStorage.setItem('ht-theme', '{theme}')")
                page.goto(base + "/")
                page.wait_for_function("typeof EV !== 'undefined' && EV.length > 0 && typeof booted !== 'undefined' && booted", timeout=20000)
                for t in ("overview", "health", "medications", "timeline", "heatmap", "labs", "costs"):
                    open_tab(t)
                    settle(300)
                    axe_at(page, f"{theme} {t}", outline=True)
                    if theme == "light":   # (#1061) and at 360 px, with the line a source that stopped syncing shows (app.js syncWarning) shown
                        page.set_viewport_size({"width": 360, "height": 800})
                        warn1061 = js("(b => { const was = [b.hidden, b.textContent]; b.hidden = false; b.textContent ||= 'Records from a source may be out of date (browser check).'; return was; })(document.getElementById('syncWarn'))")
                        settle(200)
                        marks_bad.extend(f"{t} at 360 px: {v}" for v in js(AXE_LANDMARKS))
                        if not js("!!document.getElementById('syncWarn').closest('main, header, footer, nav, aside, [role=region][aria-label], [role=complementary], [role=contentinfo]')"):
                            marks_bad.append(f"{t} at 360 px: the sync warning in no landmark (axe passes a live region)")
                        js("([h, t]) => { const b = document.getElementById('syncWarn'); b.hidden = h; b.textContent = t; }", warn1061)
                        page.set_viewport_size({"width": 1400, "height": 900})
                        settle(200)
                    if t == "heatmap" or (t == "labs" and js("document.querySelectorAll('#charts .chart .view-seg').length")):   # as its table (#60)
                        seg = "#hmHd .view-seg button" if t == "heatmap" else "#charts .chart .view-seg button"
                        page.click(f"{seg} >> nth=1")
                        settle(200)
                        axe_at(page, f"{theme} {t} as a table")
                        page.click(f"{seg} >> nth=0")
                        settle(200)
                    if t == "costs" and js("!!document.getElementById('costView')"):   # and Costs' What you paid (#278)
                        page.click("#costView button:text-is('What you paid')")
                        settle(300)
                        axe_at(page, f"{theme} costs, what you paid", outline=True)
                        page.click("#costView button:text-is('Claims')")
                        settle(200)
                for k in ("lab", "claim", "med", "letter", "visit"):   # an event's drawer
                    if js("k => !!EV.find(e => e.k === k && !e.hidden)", k):
                        js("k => openEvent(EV.find(e => e.k === k && !e.hidden))", k)
                        settle(250)
                        axe_at(page, f"{theme} the drawer, {k}")
                        page.keyboard.press("Escape")
                        settle(150)
                open_tab("timeline")
                settle(200)
                page.click("#periodMoreBtn")
                axe_at(page, f"{theme} the More… period menu")
                page.keyboard.press("Escape")
                page.click("#chips .kind-more >> nth=0")
                axe_at(page, f"{theme} a kind's ⋯ menu")
                page.keyboard.press("Escape")
                for m in ("#addMenuBtn", "#userMenuBtn"):
                    page.click(m)
                    axe_at(page, f"{theme} {m} open")
                    page.keyboard.press("Escape")
                js("""() => { const i = el('input', {type: 'text'});
                    ask({title: 'Rename this view? (browser check)', message: ['A check of the dialog (#202).', el('label', {}, 'New name', i)], action: 'Rename', field: i}); }""")
                page.wait_for_selector("dialog.sg-ask[open]", timeout=5000)
                axe_at(page, f"{theme} the app's own dialog")
                answer_ask(page, yes=False)
                for path in (f"sources.html?profile={conn_pid}", "sharing.html?profile=1", "settings.html?profile=1"):   # (its You and Install: Account and Admin before #991)
                    page.goto(base + "/" + path)
                    page.wait_for_selector(".set-nav a[data-group]", state="attached", timeout=10000)
                    settle(300)
                    for g in js("[...document.querySelectorAll('.set-nav a[data-group]')].map(a => a.dataset.group)"):
                        open_group(page, g)
                        settle(150)
                        axe_at(page, f"{theme} {path.split('.')[0]}#{g}", outline=True)
                for path, ready in (("guide.html?profile=1#name", "#step-name:not([hidden])"), ("providers.html?q=medicare", ".dir-hit")):
                    page.goto(base + "/" + path)
                    page.wait_for_selector(ready, timeout=10000)
                    settle(200)
                    axe_at(page, f"{theme} {path.split('?')[0]}", outline=True)
                ctx = browser.new_context(viewport={"width": 1400, "height": 900}, color_scheme=theme)   # no session, the real CSP
                lp = ctx.new_page()
                lp.goto(base + "/login.html")
                lp.wait_for_selector("#u", timeout=10000)
                axe_at(lp, f"{theme} sign-in", outline=True)
                ctx.close()
            js(f"localStorage.setItem('ht-theme', {json.dumps(theme_was)})" if theme_was else "localStorage.removeItem('ht-theme')")
            check(f"WCAG 2.2 AA, axe-core: no serious or critical finding on {len(axe_seen)} pages and states, in light and dark (#202)",
                  len(axe_seen) >= 90 and not axe_bad, axe_bad[:10] or f"{len(axe_seen)} checked in {time.time() - t_axe:.0f} s")
            check("…its moderate and minor findings, listed (none fail)", True, "; ".join(axe_other[:12]) or "none")
            check("…and no link in the browser's own blue or purple, on all of them in light and dark: links are in the accent (#247)",
                  links_seen[0] > 100 and not ua_links, ua_links[:8] or f"{links_seen[0]} links")
            check("…and on all of them, light and dark, the icons (#257): no Unicode glyph left as one in a button's or link's text, "
                  "nor any symbol in any text shown but ▲ ▼ ◆ ● ■ ○ ◇, ← → and ⌘ (#355), each icon drawn (its sprite's symbol found, not 0 by 0) and hidden from screen "
                  "readers or named, and each button or link that's only an icon named", icons_seen[0] > 500 and not icon_bad,
                  icon_bad[:10] or f"{icons_seen[0]} icons")
            check(f"…and on each of the {len(outlines)} pages, exactly one h1 (the page's, not the brand), no heading level skipped and "
                  "axe-core's heading rules passing; each page's outline (#331)", len(outlines) >= 35 and not outline_bad,
                  outline_bad[:10] or " | ".join(outlines))
            check(f"…and on the same {len(outlines)}, axe-core's landmark rules passing, the records tabs at 360 px too (a source's sync warning shown): one contentinfo, all shown in a landmark (#1061)",
                  len(outlines) >= 35 and not marks_bad, marks_bad[:10])
            check(f"…and on the {sizes_seen[0]} in light, no empty table heading (axe-core's empty-table-header): one over a row's buttons is named for screen readers (#1075)",
                  sizes_seen[0] >= 45 and not th_bad, th_bad[:10])
            check(f"…and on the {sizes_seen[0]} in light, at 1400 px, every button is one of the three sizes, 24, 32 or 40 px tall (#258)",
                  sizes_seen[0] >= 45 and not sizes_bad, sizes_bad[:12])
            check(f"…and on the same {sizes_seen[0]}, no control that takes focus has a title saying what's in neither its text on the screen nor its "
                  "name: a title shows for neither the keyboard nor touch, and screen readers don't reliably read it; a tip (data-tip) says it (#371)",
                  sizes_seen[0] >= 45 and not titles_bad, titles_bad[:12])
            # the keyboard at 375 px, where the top bar is tallest: Tab from the start and Shift+Tab from the end
            t_keys, kbad = time.time(), []
            page.set_viewport_size({"width": 375, "height": 800})
            page.goto(base + "/")
            page.wait_for_function("typeof EV !== 'undefined' && EV.length > 0 && typeof booted !== 'undefined' && booted", timeout=20000)
            for t in ("overview", "timeline", "heatmap", "labs", "costs"):
                open_tab(t)
                settle(250)
                kbad += focus_walk(page, t) + focus_walk(page, t, back=True)
            for path, g in (("sources.html?profile=1", "manual"), ("settings.html?profile=1", "labs"), ("sharing.html?profile=1", "summary"), ("settings.html?profile=1", "apps")):   # (Admin's before #991)
                page.goto(base + "/" + path)
                page.wait_for_selector(".set-nav a[data-group]", state="attached", timeout=10000)
                open_group(page, g)
                settle(200)
                kbad += focus_walk(page, f"{path.split('.')[0]}#{g}") + focus_walk(page, f"{path.split('.')[0]}#{g}", back=True)
            check("keyboard at 375 px: Tab and Shift+Tab through each records tab and a group of each page, every stop showing focus "
                  "and none hidden under the top bar or a sticky header (2.4.7, 2.4.11, #202)", not kbad, kbad[:8] or f"{time.time() - t_keys:.0f} s")
            # #767: …and on a phone, what Tab brings into view has its ring (outline and offset) clear of the tab bar, not only
            # its box (the scroll padding was the bar's 57 px exactly, the ring's 5 px under it): Tab from each records tab's
            # start and Shift+Tab from its end, at 412, 360 and 320 px
            RING767 = r"""async () => { await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
              const a = document.activeElement, bar = document.querySelector('header.topbar .tabs');
              if (!a || a === document.body || !bar || getComputedStyle(bar).position !== 'fixed' || bar.contains(a)) return null;
              for (let p = a; p && p !== document.body; p = p.parentElement) { const cs = getComputedStyle(p); if (cs.position === 'fixed' || cs.position === 'sticky' || p.matches('dialog')) return null; }
              const r = a.getBoundingClientRect(), cs = getComputedStyle(a), b = bar.getBoundingClientRect().top;
              if (!r.height || cs.outlineStyle === 'none' || r.top >= b || r.height > b - 100) return null;   // (wholly under it, or taller than the room: #202's)
              const ring = r.bottom + Math.max(0, parseFloat(cs.outlineOffset) + parseFloat(cs.outlineWidth));
              return ring > b + 0.5 ? `${a.tagName.toLowerCase()}${a.id ? '#' + a.id : ''} "${(a.getAttribute('aria-label') || a.textContent || '').trim().slice(0, 24)}" ${Math.round(ring - b)} px under` : null; }"""
            bad767, n767 = {}, 0
            page.goto(base + "/?profile=1#overview")   # (the walk ended on Install)
            page.wait_for_function("typeof EV !== 'undefined' && EV.length > 0 && typeof booted !== 'undefined' && booted", timeout=20000)
            for w, h in ((412, 860), (360, 760), (320, 640)):
                page.set_viewport_size({"width": w, "height": h})
                for t in ("overview", "health", "timeline", "labs", "costs", "medications"):
                    for back in (False, True):
                        js("([t, back]) => { switchTab(t); scrollTo(0, back ? document.documentElement.scrollHeight : 0); "
                           "const s = document.createElement('span'); s.tabIndex = -1; document.querySelector('main')[back ? 'append' : 'prepend'](s); s.focus(); s.remove(); }", [t, back])
                        settle(250)
                        for _ in range(10 if back else 25):
                            page.keyboard.press("Shift+Tab" if back else "Tab")
